SELECT 'moj-all-verified-judgments-review-002-chunk-054' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"6a85b2a3-8606-54d6-94fc-3c73e1682c97","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -قيادة سيارة حتت تأثير املسكر -املدعى عليه محكوم عليه باحلد والتعزير بعد واقعة الشرب املدعى بها - تداخل احلدود -تداخل التعازير .","document_number":"34318006","case_number":"33648023","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعنيزة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/9/13","year":"1434","subject":"مسكر -شرب املسكر -قيادة سيارة حتت تأثير املسكر -املدعى عليه محكوم عليه باحلد والتعزير بعد واقعة الشرب املدعى بها - تداخل احلدود -تداخل التعازير .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 34318006 :‬تاريخه‪1434/9/13:‬هـ‬\n                    ‫رقم الدعوى‪33648023:‬‬\n             ‫رقم قرار التصديق من محكمة‬\n‫االستئناف‪ 34333196:‬تاريخه‪1434/10/18:‬هـ‬\n\n\n‫مســكر ‪ -‬شــرب املســكر ‪ -‬قيــادة ســيارة حتــت تأثيــر املســكر ‪ -‬املدعــى‬\n‫عليــه محكــوم عليــه باحلــد والتعزيــر بعــد واقعــة الشــرب املدعــى بهــا ‪-‬‬\n                                      ‫تداخــل احلــدود ‪ -‬تداخــل التعازيــر ‪.‬‬\n\n\n\n\n‫‪ -1‬احلــدود تتداخــل فمــن شــرب اخلمــر مــرارا فــا يحــد ســوى مــرة‬\n‫واحــدة قــال يف شــرح منتهــى اإلرادات ‪ ( 107/11‬حــكاه ابــن املنــذر إجمــاع‬\n‫كل مــن يحفــظ عنــه مــن أهــل العلــم ألن الغــرض الزجــر عــن إتيــان‬\n‫مثــل ذلــك يف املســتقبل وهــو حاصــل بحــد واحــد ) ينظــر مثلــه يف‬\n                                                 ‫كشــاف القنــاع ‪. 412/20‬‬\n                        ‫‪ -2‬التعازير تتداخل انظر كشاف القناع ‪. 485/20‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وقيــادة‬\n‫الســيارة حتــت تأثيره‪،‬وطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بحــد‬\n‫املســكر وعقوبــة تعزيريــة مشــددة لقــاء الســوابق ‪ ،‬حيــث قبــض علــى‬\n‫املدعــى عليــه مــن قبــل الدوريــة األمنيــة بعــد االشــتباه بــه بأنــه بحالــة‬\n‫غيــر طبيعيــة‪ ،‬وباستشــمامه اتضــح أن رائحــة املســكر تفــوح مــن‬\n‫أنفاســه‪،‬وصادق املدعــى عليــه علــى الدعــوى ‪ ،‬وأضــاف بأنــه قــد صــدر‬\n\n                                                                                      ‫‪136‬‬\n\f      ‫عليــه حكــم بحــد املســكر والتعزيــر لتكــرار شــربه بعــد واقعــة شــرب‬\n      ‫املســكر املدعــى بهــا ‪ ،‬وجــرى التخاطــب مــع فضيلــة مصــدر احلكــم‬\n      ‫بشــأن احلكــم الصــادر علــى املدعــى عليــه ‪،‬فتــم تزويــد ناظــر القضيــة‬\n      ‫بصــورة مــن القــرار ‪ ،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة بإثبــات‬\n      ‫إدانــة املدعــى عليــه بشــرب املســكر ‪،‬ورد طلــب املدعــي العــام إقامة حد‬\n      ‫املســكر والتعزيــر اكتفــاء باحلكــم الصــادر علــى املدعــى عليه‪،‬وقنــع‬\n      ‫‪،‬وصــدق احلكــم‬\n                    ‫املدعــى عليــه ‪،‬واعتــرض املدعــي العــام بــدون الئحــة ُ‬\n                                                      ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة العامــة‬\n      ‫بعنيــزة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بعنيــزة برقــم ‪ 33648023‬وتاريــخ ‪1433/11/13‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 331992000‬وتاريــخ ‪1433/11/10‬ه ـ يف يــوم األحد‬\n      ‫املوافق‪1434/01/11‬هـ افتتحت اجللســة الســاعة ‪ 09 : 00‬وفيها حضر‬\n      ‫املدعــي العــام ولــم يحضــر املدعــى عليــه لــذا رفعــت اجللســة ويف جلســة‬\n      ‫أخــرى حضــر املدعــي العــام ‪.....‬وادعــى قائــا بصفتــي مدعي ـ ًا عام ـ ًا يف‬\n      ‫دائــرة التحقيــق واالدعــاء العــام مبحافظــة عنيــزة أدعــي علــى‪،..... -1‬‬\n      ‫البالــغ مــن العمــر (‪ )47‬عامـ ًا ‪ ،‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم (‪ ).....‬متــزوج ‪ ،‬متعلــم ‪ ،‬متســبب‪ ،‬يقيــم يف محافظــة عنيــزة‪ ،‬افــرج‬\n      ‫عنــه بالكفالــة احلضوريــة‪ .‬اســتنادا للمــادة (‪ )120‬مــن نظــام اإلجــراءات‬\n      ‫اجلزائيــة إنــه بتاريــخ ‪1432/8/26‬ه قبــض علــى املدعــى عليــه مــن‬\n      ‫الدوريــات األمنيــة إثــر االشــتباه بــه أنــه بحالــة غيــر طبيعية‪ .‬وباستشــمامه‬\n\n‫‪137‬‬\n\f‫اتضــح أن رائحــة املســكر مــن نــوع كلونيــا تفــوح مــن انفاســه‪ .‬وبتاريــخ‬\n‫‪1433/8/13‬ه قبــض علــى املدعــى عليــه مــن قبــل الدوريــات االمنيــة‬\n‫وهــو يقــود ســيارته وبإســتيقافه بعــد االشــتباه بوضعــه اتضــح أنــه‬\n‫بحالــة غيــر طبيعيــة ‪.‬وباستشــمامه اتضــح انبعــاث رائحــة املســكر مــن‬\n‫نــوع عــرق مــن أنفاســه وباســتجوابه أقــر بشــرب الكلونيــا املســكرة‬\n‫يف القضيــة األولــى ويف القضيــة الثانيــة أقــر بشــرب العــرق املســكر‬\n‫وانتهــى التحقيــق معــه إلــى اتهامــه بشــرب املســكر و قيــادة الســيارة‬\n‫حتــت تأثيــره‪ .‬وذلــك لألدلــة و القرائــن التاليــة ‪-1:‬مــاورد يف أقوالــه‬\n‫املدونــة علــى الصفحــة رقــم (‪ )3.2‬مــن ملــف إجــراءات االســتدالل لفــة‬\n‫(‪ )1‬و الصفحــة (‪ )3‬مــن اللفــة (‪-2.)17‬محضــري القبــض املدونــان علــى‬\n‫اللفــة رقــم (‪-3.)19.3‬محضــري االستشــمام املدونــان علــى ص رقــم (‪)1‬‬\n‫اللفــة (‪ )1‬وص (‪ )2‬مــن اللفــة (‪.)17‬وبالبحــث عمــا إذا كان لــه ســوابق‬\n‫عثــر علــى إحــدى وعشــرين ســابقة منهــا ثمانيــة عشــرة ســابقة شــرب‬\n‫مســكرات‪(.‬مت معاقبتــه علــى قيــادة الســيارة حتــت تأثيــر املســكر‬\n‫مبوجــب خطــاب املــرور رقــم (‪ ).....‬وتاريــخ (‪1433/10/16‬ه) وحيــث إن‬\n‫مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرعا أطلــب أثبــات‬\n‫أدانتــه مبــا أســند إليــه و احلكــم عليــه بحــد شــرب املســكر وبعقوبــة‬\n‫تعزيريــة مشــددة تزجــره و تــردع غيــره لقــاء ســوابقه التــي لــم تردعــه‬\n‫عقوباتهــا هكــذا ادعــى املدعــي العــام وبعــرض دعــواه علــى املدعــى‬\n‫عليــه أجــاب قائــا مــا ذكــره املدعــي العــام يف دعــواه مــن أنــه قبــض‬\n‫علــي بتاريــخ ‪1432/8/26‬ه ـ وتاريــخ ‪1433/8/13‬ه ـ لشــربي املســكر‬\n‫فهــذا كلــه صحيــح وقــد شــربت العــرق املســكر وأنــا تائــب ونــادم وقــد‬\n‫صــدر علــي حكــم بحــد املســكر والتعزيــر لتكــرار شــربه مــن قبــل‬\n\n\n                                                                                  ‫‪138‬‬\n\f      ‫فضيلــة القاضــي بهــذه احملكمــة ‪.....‬واحلكــم صــدر بعــد واقعــة شــربي‬\n      ‫للمســكر املدعــى بهــا لديكــم هكــذا أجــاب املدعــى عليــه وقــد‬\n      ‫جــرى التخاطــب مــع فضيلــة الشــيخ ‪.....‬بشــأن احلكــم الــذي صــدر علــى‬\n      ‫املدعــى عليــه مــن فضيلتــه فزودنــا فضيلتــه بصــورة القــرار الشــرعي رقــم‬\n      ‫‪ 34217680‬يف ‪1434/5/20‬ه ـ الصــادر مــن فضيلتــه بهــذه احملكمــة‬\n      ‫وقــد تضمــن القــرار ادعــاء املدعــي العــام علــى املدعــى عليــه بأنــه شــرب‬\n      ‫املســكر يف ‪1433/11/6‬ه ـ وطلــب املدعــي العــام احلكــم علــى املدعــى‬\n      ‫عليــه بحــد املســكر وتعزيــره لقــاء تكــرار شــربه وقــد أثبــت فضيلتــه‬\n      ‫إدانــة املدعــى عليــه بشــرب املســكر وحكــم عليــه بحــد املســكر‬\n      ‫ثمانــن جلــدة وبتعزيــره لقــاء تكــرار شــرب املســكر بســجنه ملــدة ثــاث‬\n      ‫ســنوات وجلــده أربعمائــة جلــدة مفرقــة وقــد قــرر املدعــي العــام واملدعــى‬\n      ‫عليــه القناعــة انتهــى مضمــون القــرار وأرفقــت صورتــه باملعاملــة وقــد‬\n      ‫ختمــت مبــا يفيــد مطابقتهــا ألصلهــا فبنــاء علــى مــا تقــدم مــن دعــوى‬\n      ‫املدعــي العــام ونظــرا إلــى أن املدعــى عليــه دفــع بأنــه حكــم عليــه بحــد‬\n      ‫املســكر والتعزيــر بعــد واقعــة شــربه للمســكر التــي لدينــا ونظــرا‬\n      ‫إلــى اطالعنــا علــى القــرار الشــرعي املذكــور والــذي يؤيــد مــا دفــع بــه‬\n      ‫املدعــى عليــه حيــث حكــم علــى املدعــى عليــه بحــد املســكر والتعزيــر‬\n      ‫لتكــرار شــربه واحلكــم صــدر بعــد الواقعــة املدعــى بهــا لدينــا ونظــرا‬\n      ‫إلــى أن احلــدود تتداخــل فمــن شــرب اخلمــر مــرارا فــا يحــد ســوى مــرة‬\n      ‫واحــدة قــال يف شــرح منتهــى اإلرادات حــكاه ابــن املنــذر إجمــاع كل‬\n      ‫مــن يحفــظ عنــه مــن أهــل العلــم ألن الغــرض الزجــر عــن إتيــان مثــل‬\n      ‫ذلــك يف املســتقبل وهــو حاصــل بحــد واحــد وكالكفــارات مــن جنــس‬\n      ‫ينظــر شــرح منتهــى اإلرادات ‪ 107/11‬وكشــاف القنــاع ‪ 412/20‬وألن‬\n\n\n‫‪139‬‬\n\f‫التعازيــر تتداخــل ينظــر كشــاف القنــاع ‪ 485/20‬وملــا تقــدم كلــه فقــد‬\n‫ثبــت لــدي إدانــة املدعــى عليــه بشــرب املســكر يف ‪1432/8/26‬ه ـ وثبت‬\n‫لــدي إدانتــه بشــرب املســكر يف ‪1433/8/13‬ه ـ ورددت طلــب املدعــي‬\n‫العــام إقامــة احلــد والتعزيــر علــى املدعــى عليــه اكتفــاء باحلكــم الصــادر‬\n‫علــى املدعــى عليــه مــن فضيلــة الشــيخ القاضــي بهــذه احملكمــة بالقــرار‬\n‫الشــرعي ‪ 34217680‬يف ‪1434/5/20‬ه ـ وبذلــك حكمــت وبعــرض‬\n‫احلكــم علــى املدعــى عليــه قنــع بــه وبعــرض احلكــم علــى املدعــي‬\n‫العــام قــرر عــدم القناعــة وطلــب رفــع احلكــم حملكمــة االســتئناف‬\n‫بــدون الئحــة اعتراضيــة وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                         ‫وصحبــه وســلم حــرر يف ‪1434/09/10‬ه ـ ‪.‬‬\n‫ال ـح ـمـ ــد ل ـلـ ــه وحـ ــده وب ـعـ ــد‪ ...‬ف ـقـ ــد اط ـل ـعـ ــنا ن ـحـ ــن ق ـضـ ــاة الــدائـ ــرة‬\n‫األولـ ــى ل ـتــدق ـيـ ــق ال ـق ـضــايـ ــا ال ـجــزائ ـيـ ــة ب ـم ـح ـك ـمـ ــة االس ـت ـئ ـنـ ــاف‬\n‫ب ـم ـن ـط ـقـ ــة ال ـق ـص ـيـ ــم عـل ــى الـمـع ــاملة الــواردة مــن فضيلــة رئي ـ ــس‬\n‫احملكمــة العامــة مبحافظــة عنيــزة برقــم(‪ )341031616‬وتاريــخ‬\n‫‪1434/9/16‬هــ؛ املقيــدة لدينــا برقــم (‪ )342235288‬وتاريــخ‬\n‫‪1434/9/22‬هــ؛ املرفــق بهــا القــرار رقــم (‪ )34318006‬وتاريــخ‬\n‫‪1434/9/13‬هــ؛ الصــادر مــن فضيلــة الشــيخ‪...../‬القاضي باحملكمــة‬\n‫؛اخلــاص بدعــوى املدعــي العــام ضــد‪ ...../‬التهامــه بشــرب املســكر ‪،‬‬\n‫وقــد تضمــن القــرار حكــم فضيلتــه بســجن وجلــد املدعــى عليــه ‪ ،‬علــى‬\n‫النحــو املفصــل فيــه‪ ،‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n‫‪ ،‬قررنــا املصادقــة علــى احلكــم ‪ ،‬واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                                                            ‫محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n                                                                                                             ‫‪140‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":136,"source_page_end":140,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ce1a316be89eafacdba39f8fb72c6a406fe8c6ae3e621dbe3dc157ceec402783","normalized_text_hash":"2bdc58e1f99308b993cdce82292700b39265fac9fa2714155a4cd7372a5ca543","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p136-34318006"},{"id":"da64904d-90b5-5a37-b844-206c16b3cfda","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -اعتداء على شخص -إمهال املدعي العام أكثر من مرة إلحضار بينته ولم يحضرها -التعزير باجللد يف مكان عام وأخذ التعهد عليه .","document_number":"34365153","case_number":"33659755","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/20","year":"1434","subject":"مسكر -شرب املسكر -اعتداء على شخص -إمهال املدعي العام أكثر من مرة إلحضار بينته ولم يحضرها -التعزير باجللد يف مكان عام وأخذ التعهد عليه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 34365153:‬تاريخه‪1434/11/20:‬هـ‬\n                          ‫رقم الدعوى‪33659755:‬‬\n                   ‫رقم قرار التصديق من محكمة‬\n      ‫االستئناف‪ 35114421:‬تاريخه‪1434/01/14 :‬هـ‬\n\n\n      ‫مســكر ‪ -‬شــرب املســكر ‪ -‬اعتــداء علــى شــخص ‪ -‬إمهــال املدعــي العــام‬\n      ‫أكثــر مــن مــرة إلحضــار بينتــه ولــم يحضرهــا‪ -‬التعزيــر باجللــد يف‬\n                                           ‫مــكان عــام وأخــذ التعهــد عليــه ‪.‬‬\n\n\n\n\n      ‫‪ -1‬قولــه تعالــى ( يأيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب‬\n         ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون ) ‪.‬‬\n       ‫‪ -2‬قوله صلى اهلل عليه وسلم (كل مسكر خمر وكل خمر حرام ) ‪.‬‬\n      ‫‪ -3‬حديــث معاويــة القشــيري أن النبــي صلــى اهلل عليــه وســلم حبــس‬\n      ‫ا يف تهمــة رواه أبــو داود يف ســننه وســكت عنــه وقــال يف رســالته‬     ‫رج ـ ً‬\n      ‫ألهــل مكــة بــأن كل مــا ســكت عنــه فهــو صالــح ورواه الترمــذي يف ســننه‬\n                                                                    ‫وحســنه ‪.‬‬\n                                      ‫‪ -4‬املادة ‪ 122‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر ومهاجمــة أحــد‬\n      ‫األشــخاص وهــو يف حالــة ســكر وطلــب إثبــات مــا أســند إليــه واحلكــم‬\n      ‫عليــه بحــد املســكر وعقوبــة تعزيريــة لقــاء الســوابق ‪ ،‬حيــث قبــض‬\n      ‫علــى املدعــى عليــه مــن قبــل الدوريــات األمنيــة إثــر بــاغ مــن حــارس أمــن‬\n\n‫‪141‬‬\n\f‫بنــك بقيــام املدعــى عليــه بالتهجــم عليــه وهــو يف حالــة ســكر وبانتقــال‬\n‫الدوريــة اتضــح أنــه بحالــة غيــر طبيعيــة وباستشــمامه انبعثــت رائحــة‬\n‫املســكر مــن فمــه ‪،‬صــادق املدعــى عليــه علــى القبــض عليــه وأنكــر‬\n‫تعاطــي املســكر وأن التهمــة لُبســت لــه ملشــاجرته أحــد األشــخاص ‪،‬‬\n‫وحيــث إن بينــة املدعــي العــام محضــر االستشــمام فقــد أمهلته احملكمة‬\n‫عــدة جلســات إلحضــار البينــة ولــم يحضرهــا فجــرى إفهامــه بأنــه ال‬\n‫مهلــة لــه بنــاء علــى املــادة ‪ 122‬مــن نظــام املرافعــات الشــرعية ‪،‬وحيــث‬\n‫إن املدعــى عليــه أنكــر شــرب املســكر ومبــا أنــه ال بينــة للمدعــي‬\n‫العــام ســوى محضــر االستشــمام وكثــرة الســوابق وذلــك يوجــه التهمــة‬\n‫القويــة وال يرقــى إلثبــات اإلدانــة ‪،‬صــرف النظــر عــن طلــب املدعــي العــام‬\n‫بإثبــات شــرب املدعــى عليــه للمســكر وإقامــة حــد املســكر وحكمــت‬\n‫احملكمــة عليــه بجلــده خمســن جلــدة تعزيــر ًا وأخــذ التعهد عليــه بالبعد‬\n‫عــن مواطــن الشــبهة وعــدم تكــرار ذلــك وقنــع املدعــى عليــه واعتــرض‬\n               ‫‪،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬    ‫املدعــي العــام ُ‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم ‪33659755‬‬\n‫وتاريــخ ‪1433/11/17‬ه ـ املقيــدة باحملكمــة برقــم ‪332043145‬‬\n‫وتاريــخ ‪1433/11/17‬ه ـ ففــي يــوم األربعــاء املوافــق‪1433/11/17‬‬\n‫ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 15‬وفيهــا حضــر املدعــي العــام ‪.....‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬املكلــف مبوجــب‬\n\n                                                                                    ‫‪142‬‬\n\f      ‫اخلطــاب رقــم ‪.....‬يف ‪1432/01/16‬ه ـ الصــادر مــن رئيــس دائــرة االدعــاء‬\n      ‫ا بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة‬    ‫العــام مبحافظــة جــدة وادعــى قائ ـ ً‬\n      ‫االدعــاء العــام مبحافظــة جــدة أدعــي ‪ 43 .....‬عام ـ ًا ســعودي اجلنســية‬\n      ‫يحمــل الســجل املدنــي رقــم (‪ ).....‬املقــدم للمحاكمــة رفــق الئحــة‬\n      ‫الدعــوى بشــربه املســكر ألنــه بتاريــخ ‪1433/11/14‬ه ـ مت القبــض‬\n      ‫علــى املدعــى عليــه مــن قبــل الدوريــات األمنيــة أثــر بــاغ مــن حــارس‬\n      ‫األمــن يف البنــك األهلــي الواقــع بحــي ‪.....‬املدعــو ‪..... /‬بقيــام املدعــى‬\n      ‫عليــه بالتهجــم عليــة وهــو يف حالــة ســكر وبانتقــال الدوريــة اتضــح انــه‬\n      ‫يف حالــة غيــر طبيعيــة وباستشــمامه انبعثــت رائحــة املســكر مــن فمــه‬\n      ‫وقــد خلــص التحقيــق معــه إلــى توجيــه االتهــام لــه مبــا اســند إليــه وذلــك‬\n      ‫لألدلــة والقرائــن املرصــودة يف ملــف الدعــوى وبالبحــث عــن ســوابق‬\n      ‫عثــر لــه علــى اثنــي عشــر ســابقة (تســع ســوابق منهــا ســكر حــد يف‬\n      ‫ثمــان منهــا إحداهــا مقترنــة بخطــف وفعــل فاحشــة اللــواط وأخــري‬\n      ‫بالنهــب وثالثــة مقترنــة بقيــادة ســيارة وهــو يف حالــة ســكر ومخــدرات‬\n      ‫وســابقة اعتــداء وســرقة ســيارات وســابقة اشــتباه نهــب وســابقة دخــول‬\n      ‫منــزل لغــرض ســيء) وحيــث أن مــا أقــدم عليــه املذكــور فعــل محرمــا‬\n      ‫معاقبــا عليــه شــرعا لــذا فإننــي أطلــب اثبــات مــا أســند إليــه واحلكــم‬\n      ‫عليــه بحــد املســكر وبعقوبــة تعزيزيــة مشــددة ورادعــة لتعــدد ســوابقه‬\n      ‫يف شــرب املســكرات وعــدم ارتداعــه مــن الســابق اســتنادا لقــرار هيئــة‬\n      ‫كبــار العلمــاء رقــم (‪ )53‬وتاريــخ ‪1397/4/4‬ه ـ هكــذا ادعــى وبســؤال‬\n      ‫ا مــا ذكــره املدعــي العــام مــن مــكان القبــض‬      ‫املدعــى عليــه أجــاب قائـ ً‬\n      ‫وتاريخــه فهــو صحيــح وأمــا مــا ذكــره بخصــوص أنــي أتعاطــي املســكر‬\n      ‫فهــو غيــر صحيــح وأنــا لــم أشــرب املســكر وكل مــا يف األمــر أنــي‬\n\n\n‫‪143‬‬\n\f‫تشــاجرت مــع أحــد األشــخاص وأبلــغ عنــي مركــز الشــرطة وألبســني‬\n‫تهمــة شــرب املســكر ولــم يجــدوا معــي مســكر وليــس هنــاك محضــر‬\n‫استشــمام وعلــي اثنــي عشــرة ســابقة وقــد تبــت مــن ذلــك وهلل احلمــد‬\n‫ا أطلــب‬    ‫هكــذا أجــاب وبســؤال املدعــي العــام عــن البينــة أجــاب قائ ـ ً‬\n‫املهلــة إلحضارهــا ويف جلســة أخــرى افتتحــت اجللســة يــوم اخلميــس‬\n‫املوافــق ‪1434/11/06‬ه ـ الســاعة ‪ 10:00‬وحضــر فيهــا املدعــي العــام‬\n‫واملدعــى عليــه وبســؤال املدعــي العــام هــل أحضــرت البينــة علــى دعــواك‬\n‫التــي أمهلــت مــن أجلهــا قــال ال واطلــب املهلــة إلحضارهــا فأفهمتــه أنــه ال‬\n‫مهلــة لــه بنــاء علــى املــادة (‪ )122‬مــن نظــام املرافعــات الشــرعية ولوائحــه‬\n‫التنفيذيــة ألنــه أمهــل ثــاث مــرات بنــاء علــى الطلــب األول برقــم ‪.....‬يف‬\n‫‪1433/11/22‬ه ـ والطلــب الثانــي برقــم ‪.....‬يف ‪1434/1/12‬ه ـ والطلــب‬\n‫الثالــث برقــم ‪.....‬يف ‪1434/2/19‬ه ـ هــذا وقــد جرى االطــاع على أوراق‬\n‫املعاملــة ومــا جــاء فيهــا فوجــدت محضــر استشــمام علــى اللفــة رقــم ‪12‬‬\n‫صفحــة رقــم ‪ 2‬وهــو يفيــد التهمــة ومــا جــاء يف دفتــر التحقيــق مــن أقــوال‬\n‫للمدعــى عليــه مطابــق إلنــكاره يف مجلــس احلكــم فبنــاء علــى مــا تقــدم‬\n‫مــن الدعــوى وجوابهــا ومــا قــرره الطرفــان وحيــث أنكــر املدعــى عليــه‬\n‫شــربه املســكر وحيازتــه وال بينــة للمدعــى العــام ســوى مــا جــاء يف‬\n‫محضــر االستشــمام وكثــرة الســوابق وكل ذلــك يــورث التهمــة القويــة‬\n‫وال يرقــي إلــى إثبــات اإلدانــة ولقولــه تعالــى‪ (:‬يــا أيهــا الذيــن آمنــوا إمنــا‬\n‫اخلمــر وامليســر واألنصــاب واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه‬\n‫لعلكــم تفلحــون ) ولقولــه صلــى اهلل عليــه وســلم ( كل مســكر خمــر‬\n‫وكل خمــر حــرام) رواه مســلم وألنــه مــن أربــاب الســوابق وملــا جــاء يف‬\n‫ا‬\n‫حديــث معاويــة القشــيري أن النبــي صلــى اهلل عليــه وســلم حبــس رجـ ً‬\n\n\n                                                                                           ‫‪144‬‬\n\f      ‫يف تهمــة رواه ابــو داود يف ســننه وســكت عنــه وقــال يف رســالته ألهــل‬\n      ‫مكــة بــأن كل مــا ســكت عنــه فهــو صالــح ورواه الترمــذي يف ســننه‬\n      ‫وحســن ولــكل مــا تقــدم فقــد صرفــت النظــر عــن طلــب املدعــى العــام‬\n      ‫بإثبــات إدانــة املدعــى عليــه بشــرب املســكر وإقامــة حــد املســكر لعــدم‬\n      ‫البينــة الكافيــة وحكمــت علــى املدعــى عليــه ‪ .....‬لقــاء التهمــة مبــا يلــي‬\n                                 ‫أوالً‪ :‬جلده خمسني جلدة دفعة واحدة علن ًا تعزير ًا‬\n                ‫ثانياً‪ :‬أخذ التعهد بالبعد عن مواطن الشبهة وعدم تكرار ذلك‬\n      ‫وبعــرض احلكــم علــى املدعــى عليــه قــرر القناعــة واملدعــي العــام قــرر‬\n      ‫عــدم القناعــة وأف ِهــم بــأن عليــه تقــدمي الئحــة اعتراضيــة خــال مــدة‬\n      ‫ثالثــن يومـ ًا مــن اســتالم نســخة احلكــم خــال عشــره أيــام وإال ســقط‬\n      ‫حقــه يف االعتــراض وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                         ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/11/06‬ه ـ‬\n                  ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده وبعد ‪:‬‬\n      ‫نحــن قضــاة الدائــرة اجلزائيــة السادســة مبحكمــة االســتئناف مبكــة‬\n      ‫املكرمــة جــرى منــا االطــاع علــى املعاملــة الــواردة إلــى هــذه احملكمــة‬\n      ‫بكتــاب فضيلــة رئيــس احملكمــة اجلزائيــة بجــدة رقــم(‪)33/2043145‬‬\n      ‫وتاريخ(‪1435/1/7‬هــ) املرفــق بهــا القــرار رقــم(‪)34365153‬‬\n      ‫وتاريخ(‪1434/11/20‬هـ)الصــادر مــن فضيلــة الشــيخ‪...../‬القاضي‬\n      ‫باحملكمــة اجلزائيــة بجــدة‪ ،‬املتضمــن دعــوى املدعــي العــام ضــد‪...../‬‬\n      ‫ســعودي اجلنســية ‪ ،‬املتهــم بشــرب املســكر ‪ ،‬احملكــوم فيــه مبــا دون‬\n      ‫باطنــه ‪ ،‬وبدراســة القــرار وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت‬\n      ‫املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                                                        ‫وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n‫‪145‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":141,"source_page_end":145,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b3136ee210f13ce05d7d814c025a62491ce0e7062558eacbed7c849e3ad604b3","normalized_text_hash":"66d310d0e68436a04d81665d82ea15022197e2854c5241c913ef32b5a77a9b50","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p141-34365153"},{"id":"3131bede-ce30-55d4-8026-9b51471618e7","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -حد املسكر -حيازته بقصد الشرب -تعزير بالسجن واجللد للشبهة وللسوابق .","document_number":"3418756","case_number":"33670840","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/20","year":"1434","subject":"مسكر -شرب املسكر -حد املسكر -حيازته بقصد الشرب -تعزير بالسجن واجللد للشبهة وللسوابق .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك‪ 3418756:‬تاريخه‪1434/1/20:‬هـ‬\n                  ‫رقم الدعوى‪33670840:‬‬\n            ‫رقم قرار التصديق من محكمة‬\n‫االستئناف‪ 3439059:‬تاريخه‪1434/02/17 :‬هـ‬\n\n\n‫مســكر ‪ -‬شــرب املســكر ‪ -‬حــد املســكر ‪ -‬حيازتــه بقصــد الشــرب ‪ -‬تعزيــر‬\n                                   ‫بالســجن واجللــد للشــبهة وللســوابق ‪.‬‬\n\n\n\n\n‫‪ -1‬قولــه صلــى اهلل عليــه وســلم ( مــن شــرب اخلمــر فاجلــدوه ) رواه‬\n                                          ‫أحمــد وأبــو داود والنســائي ‪.‬‬\n‫‪ -2‬إجمــاع الصحابــة علــى جلــد شــارب اخلمــر ثمانــن جلــده وهــو‬\n     ‫املذهــب وعليــه جماهيــر األصحــاب (كشــاف القنــاع ‪)99/14‬‬\n                                                  ‫و( االنصاف ‪.)441/15‬‬\n            ‫‪ -3‬قرار هيئة كبار العلماء رقم (‪ )53‬بتاريخ ‪1397/4/4‬هـ ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وحيازتــه‬\n‫بقصــد الشــرب ‪ ،‬وطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بحــد‬\n‫املســكر وتعزيــره للســوابق وحيــازة املســكر ‪ ،‬حيــث قبــض علــى‬\n‫املدعــى عليــه مــن قبــل الدوريــات األمنيــة وقــد كان مســتلقي ًا علــى‬\n‫األرض وبحوزتــه قــارورة حتتــوي علــى مــادة بيضــاء ‪،‬وباستشــمامه تبــن‬\n‫انبعــاث رائحــة املســكر منــه ‪،‬وأقــر املدعــى عليــه بالشــرب وأنكــر‬\n‫احليــازة ‪،‬ومبــا أن املدعــى عليــه أقــر بشــرب املســكر ‪،‬وبنــاء علــى مــا‬\n\n                                                                                 ‫‪146‬‬\n\f      ‫تقــدم حكمــت احملكمــة بجلــده ثمانــن جلــده دفعــه واحــدة يف مــكان‬\n      ‫عــام حــد املســكر ‪،‬وعــدم ثبــوت إدانــة املدعــى عليــه بحيــازة املســكر‬\n      ‫وتعزيــره بالســجن ســبعة أشــهر وجلــده مائتــي جلــده مفرقــة علــى دفعــات‬\n      ‫متســاوية لقــاء شــبهة احليــازة وتكــرار الســوابق ‪،‬وقنــع املدعــى عليــه‬\n      ‫وصــدق احلكــم مــن‬ ‫باحلكــم واعتــرض املدعــي العــام بــدون الئحــة ‪ُ ،‬‬\n                                                           ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n      ‫أنــا ‪ .....‬القاضــي باحملكمــة اجلزائيــة بالدمــام بنــاء علــى املعاملــة الــواردة‬\n      ‫مــن هيئــة التحقيــق واالدعــاء العــام واملقيــدة لــدى احملكمــة برقــم‬\n      ‫‪ 332089831‬وتاريــخ ‪1433/11/22‬ه ـ واحملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة بالدمــام برقــم ‪ 33670840‬وتاريــخ ‪1433/11/22‬هـ‬\n      ‫افتتحــت اجللســة يف يــوم الثالثــاء ‪1434/1/20‬ه ـ الســاعة التاســعة‬\n      ‫ا فيهــا‬\n             ‫وخمســة وأربعــن دقيقــة وفيهــا قــدم املدعــي العــام ‪ .....‬دعــواه قائـ ً‬\n      ‫بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة االدعــاء العــام لفــرع املنطقــة الشــرقية‬\n      ‫أدعــي علــى‪..... /‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬‬\n      ‫حيــث إنــه باالطــاع علــى محضــر االنتقــال والقبــض والتفتيــش املعــد‬\n      ‫مــن الدوريــات األمنيــة بالدمــام بتاريــخ يــوم االثنــن ‪1433/10/23‬ه ـ‬\n      ‫تبــن أنــه مت القبــض علــى املدعــى عليــه اثــر ورود بــاغ للعمليــات مــن‬\n      ‫العثــور عليــه ملقــى علــى األرض يف داخــل الســوق وعنــد الوصــول إليــه‬\n      ‫تبــن أنــه بحالــة ســكر ومت العثــور بحوزتــه علــى قــارورة مــاء صحــة‬\n      ‫صغيــرة حتتــوي علــى مــادة شــفافة بيضــاء اللــون مت بعثهــا للمركــز‬\n\n‫‪147‬‬\n\f‫اإلقليمــي للســموم لفحصهــا وباستشــمامه تبــن انبعــاث رائحــه املســكر‬\n‫منــه وبســماع أقوالــه أقــر بشــربه للمســكر وأنكــر حيازتــه ملــا مت‬\n‫ضبطــه مــن املســكر بحوزتــه وقــد انتهــى التحقيــق إلــى اتهــام‪..... /‬‬\n‫باآلتــي‪ -1 :‬بشــرب املســكر ‪ -2‬بحيازتــه لقــارورة حتتــوي علــى املــادة‬\n‫املســكرة بقصــد الشــرب وذلــك لألدلــة والقرائــن التاليــة ‪ -1:‬مــا ورد‬\n‫يف أقوالــه املنــوه عنهــا علــى الصفحــة رقــم (‪ )10-9‬مــن ملــف التحقيــق‬\n‫علــى اللفــة رقــم (‪ -2 )1‬محضــر االنتقــال والقبــض والتفتيــش املنــوه عنــه‬\n‫علــى اللفــة رقــم (‪ -3 )2‬محضــر االستشــمام املنــوه عنــه علــى الصفحــة‬\n‫رقــم (‪ )6‬مــن ملــف التحقيــق علــى اللفــة رقــم (‪ )1‬وباحلــث عــن ســوابقه‬\n‫عثــر لــه علــى أربــع ســوابق ثــاث شــرب مســكر والرابعــة اشــتباه ســكر‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرعا‬\n‫فعــل محــرم ومعاقــب عليــه شــرعا أطلــب اثبــات مــا أســند إليــه واحلكــم‬\n‫عليــه باالتــي‪ -1:‬حــد املســكر لقــاء شــربه للمســكر واحلكــم عليــه‬\n‫بعقوبــة تعزيريــة وفــق قــرار هيئــة كبــار العلمــاء رقــم ( ‪ ) 53‬وتاريــخ‬\n‫‪1397/4/4‬ه ـ لقــاء تعــدد ســوابق شــرب املســكر احلديــة ‪-2‬احلكــم‬\n‫عليــه بعقوبــة تعزيريــة لقــاء حيازتــه لقــارورة حتتــوي على املادة املســكرة‬\n‫بقصــد الشــرب هكــذا ادعــى وبعــرض دعــوى املدعي العــام على املدعى‬\n‫ا مــا ذكــره املدعــي العــام مــن شــربي للمســكر فذلــك‬     ‫عليــه أجــاب قائـ ً‬\n‫صحيــح وأمــا حيــازة املســكر فغيــر صحيحــة والســوابق ال أذكــر منهــا‬\n‫إال اثنتــان فقــط وهمــا شــرب مســكر هكــذا أجــاب وبعــرض ذلــك على‬\n‫املدعــي العــام قــال مــا ذكــره املدعــى عليــه مــن عــدم حيازتــه للمســكر‬\n‫وأن الســوابق اثنتــان فذلــك غيــر صحيــح والصحيــح مــا ذكرتــه يف‬\n‫دعــواي هكــذا أجــاب ثــم جــرى ســؤال املدعــي العــام البينــة علــى دعــواه‬\n\n\n                                                                                      ‫‪148‬‬\n\f      ‫فقــال أطلــب الرجــوع إلــى املعاملــة هكــذا أجــاب ثــم جــرى الرجــوع إلــى‬\n      ‫املعاملــة فوجــدت علــى لفــة رقــم (‪ )1‬دفتــر التحقيــق ص (‪ )6‬محضــر‬\n      ‫استشــمام املتضمــن انبعــاث رائحــة املســكر مــن أنفــاس املدعــى عليــه‬\n      ‫كمــا وجــدت علــى لفــة رقــم (‪ )2‬محضــر تنفيــذ مهمــة املتضمــن طبــق مــا‬\n      ‫ذكــره املدعــي العــام يف دعــواه كمــا وجــدت علــى لفــة رقــم (‪ )13‬قــرار‬\n      ‫اتهــام املتضمــن وجــود أربــع ســوابق للمدعــى عليــه ثــاث شــرب مســكر‬\n      ‫ـاء علــى مــا تقــدم مــن دعــوى املدعــي العــام‬\n                                                      ‫والرابعــة اشــتباه ســكر فبنـ ً‬\n      ‫وإجابــة املدعــى عليــه وإقــرار بشــرب املســكر ووجــود ســابقتني شــرب‬\n      ‫مســكر وهــو بكامــل أهليتــه املعتبــرة شــرع ًا ولقولــه صلــى اهلل عليــه‬\n      ‫وســلم (مــن شــرب اخلمــر فاجلــدوه) رواه أحمــد وأبــو داود والنســائي‬\n      ‫كمــا انعقــد إجمــاع الصحابــة رضــي اهلل عنهــم علــى جلــد شــارب اخلمــر‬\n      ‫ثمانــون جلــدة (كشــاف القنــاع عــن اإلقنــاع ‪ )99/14‬وهــو املذهــب‬\n      ‫وعليــه جماهيــر األصحــاب (اإلنصــاف ‪ )441/15‬ونظــر ًا لعــدم اكتمــال‬\n      ‫البينــة علــى حيــازة املدعــى عليــه للمســكر ونظــر ًا لوجــود ســوابق شــرب‬\n      ‫ـاء علــى قــرار‬\n                     ‫مســكر للمدعــى عليــه لــم تردعــه عقوباتهــا الســابقة وبنـ ً‬\n      ‫هيئــة كبــار العلمــاء رقــم ( ‪ ) 53‬وتاريــخ ‪1397/4/4‬ه ـ لــذا كلــه فقــد‬\n      ‫ثبــت لــدي إدانــة املدعــى عليــه بشــرب اخلمــر املســكر ولــم تثبــت لــدي‬\n      ‫إدانتــه بحيازتــه للمســكر وقــررت اآلتــي‪ :‬أوالً‪ :‬جلــده ثمانــن جلــدة دفعة‬\n      ‫واحــدة حــد املســكر ويكــون التنفيــذ يف مــكان عــام يحضــره جمــع‬\n      ‫مــن النــاس‪ .‬ثاني ـاً‪ :‬ســجنه ملــدة ســبعة أشــهر حتتســب منهــا مــدة إيقافــه‬\n      ‫وجلــدة مائتــن جلــدة تعزيــر ًا مفرقــة علــى دفعــات متســاوية بــن كل‬\n      ‫دفعــة وأخــرى مــدة ال تقــل عــن عشــرة أيــام وذلــك لقــاء شــبهة حيــازة‬\n      ‫املســكر وتكــرار الســوابق علــى أن يكــون بــن تنفيــذ احلــد والتعزيــر‬\n\n\n‫‪149‬‬\n\f‫مــدة ال تقــل عــن عشــرة أيــام وبــكل مــا تقــدم حكمــت وبعــرض احلكــم‬\n‫علــى الطرفــن قــرر املدعــى عليــه القناعــة باحلكــم كمــا قــرر املدعــي‬\n‫العــام االعتــراض بــدون الئحــة اعتراضيــة وبــاهلل التوفيــق وصلــى اهلل‬\n                            ‫وســلم علــى نبينــا محمــد‪ .‬حــرر يف ‪1434/1/20‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة‬\n‫املقيــدة لــدى احملكمــة برقــم ‪/34343619‬ج‪ 2‬وتاريــخ ‪1434/2/11‬ه ـ‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبدينــة الدمــام برقــم‬\n‫‪ 33/2089831‬وتاريــخ ‪1434/2/5‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ ‪...../‬املســجل برقــم ‪3418756‬‬\n‫وتاريــخ ‪1434/1/20‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪........../‬يف‬\n‫قضيــة مســكر وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n‫املصادقــة علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                    ‫وصحبــه وســلم‪ .‬حــرر يف‪1434/2/17‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                         ‫‪150‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":146,"source_page_end":150,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"18be2091bde5653f651c563bf6c9fe3e3a0c585d5d7b594a28ab14fc729afec3","normalized_text_hash":"29efebf82920a4f1fc9afce82ba4e14102b66b2a74afcb1747c3e5a323d228c3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p146-3418756"},{"id":"d7a9689c-aafe-52dc-a6e9-970b342ad7d0","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -حيازة بقصد االستعمال -مصادقة على الدعوى -إقامة حد املسكر -التعزير بالسجن على احليازة -أخذ التعهد عليه بعدم العودة .","document_number":"33468786","case_number":"33673241","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/17","year":"1434","subject":"مسكر -شرب املسكر -حيازة بقصد االستعمال -مصادقة على الدعوى -إقامة حد املسكر -التعزير بالسجن على احليازة -أخذ التعهد عليه بعدم العودة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك ‪ 33468786‬تاريخه‪1434/1/17:‬هـ‬\n                        ‫رقم الدعوى‪33673241:‬‬\n                   ‫رقم قرار التصديق من محكمة‬\n        ‫االستئناف‪ 3425079:‬تاريخه‪1434/01/27:‬هـ‬\n\n\n      ‫مســكر ‪ -‬شــرب املســكر ‪ -‬حيــازة بقصــد االســتعمال ‪ -‬مصادقــة علــى‬\n      ‫الدعــوى ‪ -‬إقامــة حــد املســكر ‪ -‬التعزيــر بالســجن علــى احليــازة ‪ -‬أخــذ‬\n                                                   ‫التعهــد عليــه بعــدم العــودة ‪.‬‬\n\n\n\n\n      ‫‪ -1‬قــال تعالــى (يأيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب‬\n         ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون ) ‪.‬‬\n      ‫‪ -2‬مــا أخرجــه أبــوداود عــن ابــن عمــر رضــي اهلل عنهمــا أنــه صلــى‬\n      ‫اهلل عليــه وســلم قــال ( لعــن اهلل اخلمــر وشــاربها وبائعهــا ومبتاعهــا‬\n                      ‫وعاصرهــا ومعتصرهــا وحاملهــا واحملمولــة إليــه ) ‪.‬‬\n      ‫‪ -3‬قــرار هيئــة كبــار العلمــاء ‪ 53‬يف ‪1397/4/4‬ه ـ مــن أن عقوبــة شــارب‬\n      ‫اخلمــر احلــد ال التعزيــر وأن مقــداره ثمانــون جلــده يتــم تنفيــذه جملــة‬\n                                                                           ‫واحــدة ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وحيازتــه وطلب‬\n      ‫إثبــات مــا أســند إليــه واحلكــم عليــه باملقتضــى الشــرعي والتشــديد‬\n      ‫عليــه لتعــدد ســوابقه ‪،‬حيــث قبــض علــى املدعــى عليــه مــن قبــل الدوريــة‬\n      ‫األمنيــة داخــل مســبح وهــو يف حالــة غيــر طبيعيــة ومت تفتيــش ســيارته‬\n\n‫‪151‬‬\n\f‫وعثــر بهــا علــى دبــة صغيــرة بهــا مــادة غيــر معروفــة وباستشــمامها اتضــح‬\n‫أنهــا مــادة العــرق املســكر ‪،‬وصــادق املدعــى عليــه علــى دعــوى املدعــي‬\n‫‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة عليــه بحــد املســكر بجلــده‬\n‫ثمانــن جلــده دفعــة واحــدة علن ـ ًا يف مــكان عــام وتعزيــره بســجنه ســنة‬\n‫واحــدة لقــاء احليــازة وأخــذ التعهــد عليــه بعــدم العــودة ملثــل مــا بــدر منــه‬\n‫وصــدق احلكــم مــن‬    ‫‪،‬قنــع املدعــي العــام واعتــرض املدعــى عليــه بالئحــة ُ‬\n                                                            ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنا‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بنجــران وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بنجــران برقــم ‪ 33673241‬وتاريــخ ‪ 1433/11/23‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 332100533‬وتاريــخ ‪ 1433/11/23‬ه ـ ففــي يــوم‬\n‫األربعــاء املوافــق‪ 1433/11/24‬ه ـ افتتحــت اجللســة الســاعة ‪: 45‬‬\n‫‪ 11‬بشــأن دعــوى املدعــي العــام ‪.....‬واملكلــف مبهمــة اإلشــراف علــى‬\n‫مكتــب االدعــاء العــام مبحاكــم جنــران مبوجــب خطــاب رئيــس‬\n‫فــرع هيئــة التحقيــق واالدعــاء العــام مبنطقــة جنــران رقــم ‪.....‬وتاريــخ‬\n‫‪1430/12/29‬ه ـ ضــد ‪..... /‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة‬\n‫ا يف دعــواه عليــه إنــه ورد يف محضــر دوريــات األمنيــة رقــم‬ ‫رقــم ‪.....‬قائـ ً‬\n‫‪.....‬وتاريــخ ‪1432/12/27‬ه ـ أنهــا تلقــت بــاغ عــن طريــق غرفــة العمليات‬\n‫يفيــد عــن وجــود مبلــغ يف فنــدق األخــدود ومت االنتقــال إلــى الفنــدق‬\n‫ووجــد املبلــغ وأفــاد عــن وجــود شــخص داخــل املســبح ويشــتبه أنــه يف‬\n‫حالــة غيــر طبيعــة ويصــدر منــه أصــوات داخــل املســبح فتــم القبــض عليــه‬\n\n                                                                                          ‫‪152‬‬\n\f      ‫وكان داخــل املســبح ويشــتبه أنــه يف حالــة غيــر طبيعيــة وقــد مت تفتيــش‬\n      ‫الســيارة وعثــر علــى دبــة صغيــرة يوجــد بهــا أقــل مــن النصــف مــادة‬\n      ‫غيــر معروفــه وقــد مت إركاب الشــخص يف الدوريــة فقــام بتكســير‬\n      ‫البالســتيك الداخلــي للبــاب اخللفــي للدوريــة وقــد ســلم الشــخص إلــى‬\n      ‫مركــز شــرطة الفيصليــة إلكمــال الــازم كمــا جــرى االطــاع علــى‬\n      ‫محضــر االستشــمام املــؤرخ يف ‪1432/12/27‬ه ـ املعــد مــن قبــل عضــو‬\n      ‫هيئــة األمــر باملعــروف والنهــي عــن النكــر وضابــط مركــز شــرطة‬\n      ‫الفيصليــة املتضمــن ( أنهــم لــم يســتطيعوا االقتــراب مــن املذكــور ألنــه‬\n      ‫كان يف حالــة هيجــان ويهــذي بأصــوات عاليــة ويتصــرف بتصرفــات‬\n      ‫غيــر طبيعيــة ممــا يــدل علــى أنــه يف حالــة غيــر طبيعيــة وباستشــمام‬\n      ‫املــادة املضبوطــة معــه يف الســيارة اتضــح أنهــا مــادة العــرق املســكرة‬\n      ‫وباســتجواب املدعــى عليــه أقــر بقيامــه بشــرب كأســن مــن املــادة‬\n      ‫املســكرة كمــا أقــر بــأن مــا مت ضبطــه داخــل ســيارته باقــي املــادة‬\n      ‫املســكرة وقــد انتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه‬\n      ‫بشــرب مــادة العــرق املســكر وحيازتــه وذلــك لألدلــة والقرائــن التاليــة‬\n      ‫‪ -1:‬مــا جــاء يف اعترافــه املصــدق شــرع ًا واملــدون علــى ص رقــم (‪ )7‬لفــه‬\n      ‫رقــم (‪ -2 )1‬مــا جــاء يف محضــر القبــض املعــد مــن قبــل الدوريــة األمنيــة‬\n      ‫لفــه رقــم (‪ -3 )3‬مــا جــاء يف محضــر االستشــمام واملــدون علــى ص‬\n      ‫رقــم (‪ )3‬مــن ملــف التحقيــق املرفــق لفــه رقــم (‪ )1‬وبالبحــث عــن ســوابق‬\n      ‫املدعــى عليــه عثــر لــه علــى ســت ســوابق األولــى ســرقة مســاكن والثانيــة‬\n      ‫مضاربــة داخــل الســجن والثالثــة مقاومــة رجــال األمــن مضاربــة اشــتباه‬\n      ‫مســكر والرابعــة شــرب املســكرات اخلامســة اســتعمال املخــدرات‬\n      ‫السادســة شــرب املســكرات وتأسيس ـ ًا علــى مــا ســبق وألن مــا أقــدم‬\n\n\n‫‪153‬‬\n\f‫ا محرمـ ًا‬ ‫عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرع ًا يعــد فعـ ً‬\n‫معاقب ـ ًا عليــه شــرع ًا لــذا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم‬\n‫عليــه باملقتضــى الشــرعي والتشــديد عليــه نظــر ًا لتعــدد ســوابقه ولوجــود‬\n‫ثــاث ســوابق مــن جنــس القضيــة احلاليــة وبــاهلل التوفيــق هــذه دعــواي‬\n‫وبعــرض الدعــوى علــى املدعــى عليــه قــال مــا ذكــره املدعــي العــام مــن‬\n‫قيامــي بشــرب مــادة العــرق املســكرة وحيازتهــا بقصــد التعاطــي فهــو‬\n‫صحيــح جملــة وتفصيــا هكــذا أجــاب وللتأمــل ودراســة القضيــة رفعــت‬\n‫اجللســة إلــى يــوم الســبت املوافــق ‪1433/11/27‬ه ـ الســاعة العاشــرة‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n‫وســلم ‪ .‬حــرر يف ‪ 1433/11/24‬ه ـ الســاعة ‪ 12:00‬احلمــد هلل وحــده‬\n‫وبعــد فلــدي ففــي يــوم الســبت املوافــق‪ 1433/11/27‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 12:00‬وفيها حضر املدعى عليه و بعد التأمل والدراســة وبناء‬\n‫علــى مــا ســبق مــن الدعــوى واإلجابــة وحيــث إن املدعــى عليــه قــد اعتــرف‬\n‫بقيامــه بشــرب العــرق املســكر وحيازتــه بقصــد التعاطــي و ملــا كان‬\n‫شــرب العــرق املســكر وحيازتــه أمــر ًا محرم ـ ًا يف الشــريعة اإلســامية‬\n‫بدليــل قولــه تعالــى‪« :‬يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب‬\n       ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون»‬\n‫( املائدة ‪ ) 90 :‬و ما أخرجه أبو داود عن ابن عمر رضي اهلل عنهما أنه‬\n‫قــال ‪ :‬قــال رســول اهلل صلــى اهلل عليــه وســلم‪ « :‬لعــن اهلل اخلمــر وشــاربها‬\n‫وســاقيها وبائعهــا و مبتاعهــا وعاصرهــا ومعتصرهــا وحاملهــا واحملمولــة‬\n‫إليــه « ( كتــاب األشــربة ‪ ،‬البــاب ‪ :‬العنــب يعصــر للخمــر ‪ ،‬احلديــث رقــم‬\n‫‪ )3189‬واســتناد ًا علــى مــا تضمنــه قــرار هيئــة كبــار العلمــاء رقــم ‪53‬‬\n‫وتاريــخ ‪1397/4/4‬ه ـ مــن أن عقوبــة شــارب اخلمــر احلــد ال التعزيــر وأن‬\n\n\n                                                                                           ‫‪154‬‬\n\f      ‫مقــداره ثمانــون جلــدة يتــم تنفيــذه جملــة واحــدة و نظــر ًا إلــى أن املدعــى‬\n      ‫عليــه مــن أربــاب الســوابق يف حيــازة املخــدرات واســتعمالها وشــرب‬\n      ‫املســكرات ممــا يــدل علــى عــدم ارتداعــه مــن األحــكام الســابقة ولقلــة‬\n      ‫الكميــة املضبوطــة وتأسيس ـ ًا علــى جميــع مــا تقــدم فقــد قــررت مــا‬\n      ‫يأتــي أو ًال ‪ :‬ثبــت لــدي إدانــة املدعــى عليــه بقيامــه بشــرب مــادة العــرق‬\n      ‫املســكرة وحيازتهــا بقصــد التعاطــي ثاني ـ ًا ‪ :‬معاقبتــه بحــد املســكر‬\n      ‫وذلــك بجلــده ثمانــن جلــدة دفعــة واحــدة علن ـ ًا يف مــكان عــام ثالث ـ ًا ‪:‬‬\n      ‫تعزيــره لقــاء حيازتــه العــرق املســكر بقصــد التعاطــي وذلــك بســجنه‬\n      ‫ملــدة ســنة واحــدة تبــدأ اعتبــار ًا مــن تاريــخ إيقافــه رابع ـ ًا ‪ :‬يؤخــذ التعهــد‬\n      ‫الشــديد علــى املدعــى عليــه بعــدم العــودة ملثــل مــا بــدر منــه هــذا مــا ظهــر‬\n      ‫لــي وبــه حكمــت وبعــرض احلكــم علــى املدعــى عليــه لــم يقنــع بــه وطلــب‬\n      ‫رفــع احلكــم حملكمــة االســتئناف فأجبتــه لطلبــه وأفهمتــه باســتالم‬\n      ‫نســخة احلكــم بعــد عشــرة أيــام وتقــدمي الئحــة اعتراضيــة خــال ثالثــن‬\n      ‫يومـ ًا مــن تاريــخ اســتالمه نســخة احلكــم كمــا قــرر املدعــي العــام عــدم‬\n      ‫االعتــراض علــى احلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n      ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/11/27‬ه ـ الســاعة ‪12:30‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثالثــة‬\n      ‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بنجــران برقــم‬\n      ‫‪ 332100533‬وتاريــخ ‪1434/1/17‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n      ‫فضيل ــة القاضــي باحملكمــة الشــيخ ‪..... /‬برقــم ‪ 33468786‬وتاريــخ‬\n      ‫‪1433/11/29‬ه ـ اخلــاص بدعــوى املدعــي العــام ضـ ــد ‪..... /‬يف قضيــة (‬\n      ‫شــرب مــادة العــرق املســكر وحيازتــه ) علــى الصفــة املوضحــة يف القــرار‬\n\n\n‫‪155‬‬\n\f‫املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار‬\n‫وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم واهلل‬\n             ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                 ‫‪156‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":151,"source_page_end":156,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3e922d169903901de362cfb6d623c74e37205000d00958f9c7b83db9248d272b","normalized_text_hash":"749fad15ca1107df6b03caed3cf9aeb08b0af301ca24b69cc44bd01fc96c080a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p151-33468786"},{"id":"e515ce02-7758-5227-a1c0-a34c020c0e6c","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -تعاطي املسكر وحيازته -عدم حضور املدعى عليه -إيقاف النظر حلن إحضار املدعى عليه -سند إجرائي .","document_number":"34211904","case_number":"33708187","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بصبياء","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/13","year":"1434","subject":"مسكر -تعاطي املسكر وحيازته -عدم حضور املدعى عليه -إيقاف النظر حلن إحضار املدعى عليه -سند إجرائي .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 34211904 :‬تاريخه‪1434/5/13:‬هـ‬\n                          ‫رقم الدعوى‪33708187:‬‬\n                   ‫رقم قرار التصديق من محكمة‬\n      ‫االستئناف‪ 34259848:‬تاريخه‪1434/07/04 :‬هـ‬\n\n\n      ‫مســكر ‪ -‬تعاطــي املســكر وحيازتــه ‪ -‬عــدم حضــور املدعــى عليــه ‪ -‬إيقــاف‬\n                           ‫النظــر حلــن إحضــار املدعــى عليــه ‪ -‬ســند إجرائــي ‪.‬‬\n\n\n\n\n        ‫‪-1‬املادة احلادية واألربعون بعد املائة من نظام اإلجراءات اجلزائية ‪.‬‬\n                   ‫‪ -2‬املادة الثالثة والثمانني من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وحيازتــه‬\n      ‫‪،‬وطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بحــد املســكر وتعزيــره‬\n      ‫لقــاء احليــازة ‪،‬حيــث قبــض علــى املدعــى عليــه مــن قبــل الشــرطة وكان‬\n      ‫يف ســيارته إثــر االشــتباه بــه وكان حــن القبــض عليــه يف حالــة غيــر‬\n      ‫طبيعية‪،‬وباستشــمامه اتضــح انبعــاث رائحــة املســكر مــن فمــه ‪،‬حيــث‬\n      ‫إنــه لــم يحضــر رغــم تبلغــه عــن طريــق الشــرطة‪،‬فرفعت اجللســة للكتابــة‬\n      ‫بخطــاب تعقيبــي للشــرطة إلحضــار املدعــى عليــه ‪،‬إال أنــه لــم يتــم‬\n      ‫إحضــاره ‪،‬وألنــه يتعــذر احلكــم يف الدعــوى بــدون حضــور املدعــى عليــه‬\n      ‫بنــاء علــى املــادة‪ 141‬مــن نظــام اإلجــراءات اجلزائيــة ‪،‬وألن بقــاء املعاملــة‬\n      ‫دون احلكــم فيهــا إضاعــة للوقــت وإهــدار للجلســات ‪،‬فقــد مت احلكــم‬\n      ‫بإيقــاف الدعــوى حلــن إحضــار املدعــى عليــه وذلــك بنــاء علــى املــادة ‪83‬‬\n\n‫‪157‬‬\n\f‫مــن نظــام املرافعــات الشــرعية ‪،‬واعتــرض املدعــي العــام بــدون الئحــة‬\n                            ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬‫ُ‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة العامــة‬\n‫بصبيــاء وبنــاء علــى املعاملــة الــواردة لنــا مــن هيئــة التحقيــق واالدعــاء‬\n‫العــام مبحافظــة صبيــا برقــم ه ـ ج‪ 224/2/2‬وتاريــخ ‪1433/01/26‬ه ـ‬\n‫احملدثــة إحالتهــا برقــم ‪ 33078187‬وتاريــخ ‪ 1434/2/2‬ه ـ احملــدث‬\n‫قيدهــا رقــم ‪ 332257876‬ففــي يــوم الســبت املوافــق‪1434/02/02‬‬\n‫ه ـ افتتحــت اجللســة الســاعة ‪ 11 : 00‬وفيهــا قــدم املدعــي العــام بصبيــا‬\n‫‪.....‬دعــواه ضــد ‪ .....‬الغائــب عــن مجلــس احلكــم قائــا يف دعــواه انــه‬\n‫بتاريــخ ‪1432/12/29‬ه ـ مت القبــض علــى املدعــى عليــه مــن قبــل أفــراد‬\n‫البحــث والتحريــات بشــرطة صبيــا وهــو كان يف ســيارته يف محطــة‬\n‫‪.....‬أثنــاء االشــتباه فيــه وكان حــن القبــض يف حالــة غيــر طبيعيــة‬\n‫متعاطيــا ملــادة املســكر ‪ .‬وباستشــمامه اتضــح أن رائحــة املســكر تفــوح‬\n‫مــن فمــه ومت ضبــط قــارورة مــاء صحــة صغيــرة بهــا مــادة أثبــت التقريــر‬\n‫الفنــي إيجابيــة تلــك املــادة للكحــول األثيلــي املســكر بنســبة ‪%31‬‬\n‫وباســتجوابه أقــر أنــه مت القبــض عليــه عندمــا كان نائمــا يف ســيارته‬\n‫يف محطــة ‪.....‬وكان متعاطيــا ملــادة املســكر وأمــا مــادة املســكر‬\n‫التــي عثــرت بحوزتــه وهــي قــارورة مــاء صحــة صغيــر حصــل عليهــا مــن‬\n‫شــخص باكســتاني ال يعرفــه وقــد أســفر التحقيــق عــن توجيــه االتهــام‬\n‫لــه بتعاطيــه ملــادة املســكر وحيازتــه لــه وذلــك إلقــراره املــدون ص (‪)4‬‬\n‫بدفتــر التحقيــق املرفــق ومحضــر القبــض املرفــق لفــة رقــم (‪ )2‬ومحضــر‬\n\n                                                                                     ‫‪158‬‬\n\f      ‫اإلستشــمام املــدون ص (‪ )1‬بدفتــر التحقيــق املرفــق ‪ .‬والتقريــر الفنــي‬\n      ‫املرفــق رقــم (‪ )11‬وبالبحــث عــن ســوابقه لــم يعثــر لــه ســابقه مســجله‬\n      ‫وحيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرعا‬\n      ‫لــذا أطلــب إثبــات مــا نســب إليــه احلكــم عليــه بحــد املســكر ‪ ،‬وتعزيــره‬\n      ‫شــرعا لقــاء حيازتــه قــارورة مــاء صغيــر بهــا مســكر هكــذا ادعــى هــذا‬\n      ‫كمــا ســبق أن مت تبليــغ املدعــى عليــه للحضــور للمحكمــة مبوجــب‬\n      ‫خطــاب شــرطة صبيــا رقــم ‪.....‬يف ‪ 1433/02/22‬ه ـ وخطابهــم رقــم ‪.....‬‬\n      ‫يف ‪1433/08/06‬ه ـ ونظــر ًا ألن املدعــى عليــه لــم يحضــر رغــم تبلغــه‬\n      ‫وبنــاء علــى املــادة احلاديــة واألربعــن بعــد املائــة فقــد جــرت الكتابــة إلــى‬\n      ‫شــرطة صبيــا إليقافــه وإحضــاره للمحكمــة ولــم يتــم إحضــاره هــذا‬\n      ‫اليــوم وعليــه فقــد قــررت كتابــة خطــاب تعقيبــي وحتديــد موعــد آخــر‬\n      ‫ويف جلســة أخــرى حضــر املدعــي العــام ولــم يحضــر املدعــى عليــه وقــد‬\n      ‫ســبق كتابــة خطــاب إحلاقــي باألمــر بإيقــاف املدعــى عليــه وإحضــاره‬\n      ‫للمحكمــة يف هــذا اليــوم إال أنــه لــم يتــم إنفــاذ ذلــك وعليــه ونظــرا ألنــه‬\n      ‫يتعــذر احلكــم يف الدعــوى بــدون حضــور املدعــى عليــه بنــاء علــى املــادة‬\n      ‫احلاديــة واألربعــن بعــد املائــة مــن نظــام اإلجــراءات اجلزائيــة كمــا أنــه‬\n      ‫مت األمــر بإيقافــه مرتــن ولــم يتــم إنفــاذ األمــر وألن يف بقــاء املعاملــة‬\n      ‫لــدى احملكمــة دون أن ميكــن احلكــم فيهــا إضاعــة للوقــت وإهــدارا‬\n      ‫للجلســات دون طائــل لــذا فقــد قــررت إيقــاف النظــر يف هــذه الدعــوى‬\n      ‫حلــن إحضــار املدعــى عليــه بنــاء علــى املــادة الثالثــة والثمانــن مــن نظــام‬\n      ‫املرافعــات الشــرعية وبعرضــه علــى املدعــي العــام قــرر عــدم قناعتــه‬\n      ‫طالبــا رفــع املعاملــة حملكمــة االســتئناف دون الئحــة اعتراضيــة لكونــه‬\n      ‫يرغــب أن يتــم بعــث املعاملــة إلــى الشــرطة إلحضــار املدعــى عليــه بالقــوة‬\n\n\n‫‪159‬‬\n\f‫اجلبريــة وعليــه فقــد أجبتــه لطلبــه وأمــرت برفــع املعاملــة إلــى محكمــة‬\n‫االســتئناف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                               ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/05/11‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بصبيــا برقــم ‪332257876‬‬\n‫وتاريــخ ‪1434/5/25‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيل ــة القاضي‬\n‫باحملكمــة الشــيخ ‪..... /‬برقــم ‪ 34211904‬وتاريــخ ‪1434/5/13‬ه ـ‬\n‫اخلــاص بدعــوى املدعــي العــام ضــد ‪..... /‬يف قضيــة (مســكر) علــى‬\n‫الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة تقــررت‬\n‫املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                               ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪160‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":157,"source_page_end":160,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"78bfec5fed7d2365aa4467d5a4168bb05240207d08f8e1d052cd883389768c06","normalized_text_hash":"e9bb3d0cc5efe21a0eae8a9ae836053aceefe022fdd5c6d0f888a0858b141a3b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p157-34211904"},{"id":"45640cd6-c31a-563e-b339-f488177daf78","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -حيازة احلبوب املمنوعة بغرض االستعمال -تخفيف العقوبة لقلة الكمية -تدرأ احلدود بالشبهات -التعزير باجللد والسجن واملنع من السفر .","document_number":"3458980","case_number":"34107889","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعرعر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/9","year":"1434","subject":"مسكر -شرب املسكر -حيازة احلبوب املمنوعة بغرض االستعمال -تخفيف العقوبة لقلة الكمية -تدرأ احلدود بالشبهات -التعزير باجللد والسجن واملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"          ‫رقم الصك‪ 3458980:‬تاريخه‪1434/3/9:‬هـ‬\n                         ‫رقم الدعوى‪34107889:‬‬\n                   ‫رقم قرار التصديق من محكمة‬\n      ‫االستئناف‪ 34188286:‬تاريخه‪1434/04/15:‬هـ‬\n\n\n      ‫مســكر ‪ -‬شــرب املســكر ‪ -‬حيــازة احلبــوب املمنوعــة بغــرض االســتعمال‬\n      ‫‪ -‬تخفيــف العقوبــة لقلــة الكميــة ‪ -‬تــدرأ احلــدود بالشــبهات ‪ -‬التعزيــر‬\n                                         ‫باجللــد والســجن واملنــع مــن الســفر ‪.‬‬\n\n\n\n\n                  ‫‪ -1‬قوله صلى اهلل عليه وسلم ( ادرؤوا احلدود بالشبهات ) ‪.‬‬\n                  ‫‪ -2‬املادة ‪ 41‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n                  ‫‪ -3‬املادة ‪ 60‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n                  ‫‪ -4‬املادة ‪ 56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وحيــازة حبــة‬\n      ‫واحــدة مــن حبــوب االمفيتامــن وطلــب إثبــات مــا أســند إليــه واحلكــم‬\n      ‫عليه بحد املســكر وســجنه ومنعه من الســفر والتشــديد عليه للســوابق‬\n      ‫‪،‬حيــث مت االشــتباه باملدعــى عليــه مــن قبــل فرقــة مكافحــة املخــدرات‬\n      ‫وكان متوقــف أمــام منزلــه وعنــد توجــه الدوريــة لــه قــام بالتوجــه إلــى‬\n      ‫بــاب منزلــه ورمــي شــيء مــن جيبــه ومتــت الســيطرة عليــه قبــل دخولــه‬\n      ‫املنــزل وبتفتيشــه لــم يتــم العثــور علــى شــيء معه ومبشــاهدة ما قــام برميه‬\n      ‫عثــر علــى حبــة يشــتبه أن تكــون مــن احلبــوب احملظــورة وباستشــمامه‬\n\n‫‪161‬‬\n\f‫اتضــح انبعــاث رائحــة املســكر مــن أنفاســه وأثبــت التقريــر الكيميائــي‬\n‫الشــرعي إيجابيــة العينــة املضبوطــة ملــادة االمفيتامــن ‪،‬صــادق املدعــى‬\n‫عليــه علــى احليــازة وأنكــر شــرب املســكر ‪،‬وبنــاء علــى مــا تقــدم‬\n‫حكمــت احملكمــة بالســجن أربعــة أشــهر وجلــده تســع ًا وســبعني‬\n‫جلــدة تعزيــرا علــى دفعتــن األولــى قدرهــا ‪ 39‬جلــده والثانيــة قدرهــا‬\n‫‪ 40‬جلــده لقــاء توجــه التهمــة لشــرب املســكر ومنعــه مــن الســفر مــدة‬\n‫ســنتني وصــرف النظــر عــن طلــب املدعــي العــام بإقامــة حــد املســكر‬\n‫وقنــع املدعــى عليــه واعتــرض املدعــي العــام مكتفيــا بالئحــة الدعــوى‬\n                            ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬   ‫ُ‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة العامــة‬\n‫بعرعــر وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بعرعــر برقــم ‪ 34107889‬وتاريــخ ‪ 1434/03/04‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 34565415‬وتاريــخ ‪ 1434/03/04‬ه ـ ففــي يــوم‬\n‫االثنــن املوافــق‪ 1434/03/09‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 45‬‬\n‫وفيهــا حضــر املدعــي العــام ‪.....‬وادعــى قائال بصفتي مدعيـ ًا عام ًا بدائرة‬\n‫االدعــاء العــام لفــرع الهيئــة مبنطقــة احلــدود الشــمالية أدعــي ‪.....‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬فأنــه بتاريــخ ‪1434/2/19‬ه ـ‬\n‫وأثنــاء قيــام فرقــة مكافحــة املخــدرات بعملهــا املعتــاد وذلــك مبســح‬\n‫االماكــن املشــبوهة مــن مروجــي ومســتخدمي املخــدرات وأثنــاء املســح‬\n‫حلــي ‪.....‬بإســكان ‪ ..........‬مت االشــتباه يف شــخص كان متوقــف أمــام‬\n‫منزلــه وعنــد توجيــه الدوريــة الرســمية إليــه قــام بالتوجــه إلــى بــاب منزلــه‬\n\n                                                                                        ‫‪162‬‬\n\f      ‫وأخــرج شــيء مــن جيبــه األميــن وقــام برميــه ومتــت الســيطرة عليــه قبــل‬\n      ‫دخولــه املنــزل وبتفتيشــه شــخصي ًا لــم يعثــر علــى أي شــيء مــن املمنوعــات‬\n      ‫ومبشــاهدة مــا قــام برميــه عثــر علــى حبــة بنية اللون يشــتبه أن تكون من‬\n      ‫احلبــوب احملظــورة كانــت علــى األرض أمــام بــاب املنــزل‪ ،‬وباستشــمامه‬\n      ‫اتضــح انبعــاث رائحــة مــن أنفاســه تشــبه رائحــة املســكر ‪ ،‬فتــم ضبطــه‬\n      ‫‪ .‬وباســتجوابه‪ /‬أقــر بشــرب املســكر وحيــازة حبــة واحــدة مــن حبــوب‬\n      ‫االمفيتامــن احملظــورة بقصــد التعاطــي ‪ ،‬واســتعماله لنوعهــا يف‬\n      ‫الســابق ‪ .‬وقــد أثبــت التقريــر الكيميائــي الشــرعي الصــادر مــن مركــز‬\n      ‫الســموم بتبــوك رقــم (‪ ).....‬لعــام ‪1434‬ه ـ إيجابيــة العينــة املرســلة للمــادة‬\n      ‫االمفيتامــن املنبــه للجهــاز العصبــي وهــو مــن املؤثــرات العقليــة اخلاضعــة‬\n      ‫للرقابــة واملنــوه عنــه باجلــدول الثانــي فئــة (ب) يف تعميــم صاحــب الســمو‬\n      ‫امللكــي وزيــر الداخليــة رقــم (‪ )89400/19‬وتاريخ‪1426/10/25‬هــ‪.‬‬\n      ‫وقــد انتهــى التحقيــق إلــى اتهــام‪ ،...../‬بشــرب املســكر وحيــازة حبــة‬\n      ‫واحــدة مــن احلبــوب احملتويــة علــى مــادة االمفيتامــن املنبهــة للجهــاز‬\n      ‫العصبــي بقصــد االســتعمال‪ ،‬واســتعماله لنوعهــا يف الســابق ‪ ،‬املجــرم‬\n      ‫نظامــا بنــص املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة ‪ ،‬الصــادر باملرســوم امللكي رقــم (م‪ )39/‬وتاريخ ‪1426/7/8‬هـ‬\n      ‫‪.‬وذلــك لألدلــة والقرائــن التاليــة‪ -1 :‬مــا جــاء بأقوالــه املدونــة علــى‬\n      ‫محضــر االســتجواب املرفــق لفــة رقــم (‪ -2.)6-7‬مــا جــاء مبحضــر‬\n      ‫القبــض املرفــق املــدون علــى الصفحــة رقــم (‪ )12‬لفــة رقــم (‪ -3.)1‬مــا‬\n      ‫جــاء مبحضــر االستشــمام املرفــق املــدون علــى الصفحــة رقــم (‪ )13‬لفــة‬\n      ‫رقــم (‪ -4.)1‬مــا جــاء بالتقريــر الكيميائــي الشــرعي املرفــق لفــة رقــم‬\n      ‫(‪ . )23‬وحيــث أن مــا أقــدم عليــه املتهــم وهــو بكامــل أهليتــه املعتبــرة‬\n\n\n‫‪163‬‬\n\f‫شــرعا فعــل محــرم ومعاقــب عليــه شــرعا ومجــرم نظامــا بنــص املــادة‬\n‫الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪ ،‬الصــادر‬\n‫باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ لــذا أطلــب إثبــات‬\n‫إدانتــه مبــا أســند إليــه واحلكــم عليــه مبــا يلــي‪ -1 :‬عقوبــة حــد املســكر‪.‬‬\n‫‪ -2‬عقوبــة الســجن وفقــا للفقــرة األولــى مــن املــادة (‪ )41‬مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬وإعمــال الفقــرة األولــى مــن‬\n                                              ‫املــادة (‪ )62‬مــن النظــام نفســه‪.‬‬\n‫‪ -3‬عقوبــة املنــع مــن الســفر خــارج اململكــة وفقــا للفقــرة األولــى مــن‬\n‫املــادة (‪ )56‬مــن النظــام نفســه ‪ ،‬والتشــديد عليــه نظــر ًا لســوابقه‬\n‫وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه احلاضــر أجــاب قائــا ‪:‬‬\n‫مــا ذكــره املدعــي العــام مــن حيازتــي للحبــة بقصــد االســتعمال صحيــح‬\n‫ومــا ذكــره مــن شــربي للمســكر فغيــر صحيــح مطلقــا وبســؤال املدعــي‬\n‫العــام البينــة علــى شــرب املدعــى عليــه للمســكر أجــاب قائــا بينتــي مــا‬\n‫جــاء يف إقــرار لــدى املدعــى عليــه لــدى احملقــق واملرفــق لكــم بطيــات‬\n‫املعاملــة وكذلــك مــا جــاء مبحضر االستشــمام املرفــق لكم ‪ ،‬هذا وقد‬\n‫جــرى منــا االطــاع علــى محاضــر التحقيــق املرفقــة علــى لفــة رقــم (‪)7،6‬‬\n‫مــن طيــات املعاملــة ووجــدت فيهــا اقــرار املدعــى عليــه بشــرب املســكر‬\n‫وانــه كان بحالــة غيــر طبيعيــة أثنــاء القبــض عليــه وبعــرض ذلــك علــى‬\n‫املدعــى عليــه أجــاب قائــا ‪ :‬أننــي لــم أقــر بذلــك ولــم أطلــع علــى مــا‬\n‫كتــب يف التحقيــق ولــم أقــرأ ذلــك كلــه وإمنــا بصمــت مباشــرة ‪.‬هكــذا‬\n‫أجــاب كمــا جــرى منــا االطــاع علــى محضــر االستشــمام املــدون علــى‬\n‫صحيفــة رقــم (‪ )13‬مــن ملــف ضبــط إجــراءات االســتدالل يف قضايــا‬\n‫املخــدرات لفــه رقــم (‪ )1‬مــن طيــات املعاملــة ونــص احلاجــة منــه ‪ (( :‬كان‬\n\n\n                                                                                      ‫‪164‬‬\n\f      ‫تطلــع مــن فــاه رائحــة تشــبه رائحــة العــرق املســكر ‪...‬ومت التأكــد بأنهــا‬\n      ‫تشــبه رائحــة العــرق املســكر ‪ ))...‬أ‪.‬ه ـ وبعــرض ذلــك علــى املدعــى عليــه‬\n      ‫أنكــر ذلــك مطلقـ ًا ‪ ،‬وبســؤال املدعــي العــام هــل لديــه مزيــد بينــة أجــاب‬\n      ‫قائــا ‪ :‬ليــس لــدي ســوا مــا قدمتــه وبســؤال املدعــى عليــه عــن الســوابق‬\n      ‫املدونــة بســجله وعددهــا خمــس ســوابق منهــا قضيــة ترويــج للمخــدرات‬\n      ‫صــادق عليهــا جميع ـ ًا فبنــاء علــى مــا تقــدم مــن الدعــوى ومصادقــة‬\n      ‫املدعــى عليــه علــى دعــوى احليــازة وإنــكاره لدعــوى الشــرب وعــدم قيــام‬\n      ‫البينــة املوصلــة متامــا علــى ذلــك وملــا ورد عنــه صلــى اهلل عليــه وســلم مــن‬\n      ‫قولــه «ادرؤوا احلــدود بالشــبهات « ‪ .‬لــذا كلــه فقــد ثبــت لــدي إدانــة‬\n      ‫املدعــى عليــه ‪.....‬بحيــازة حبــة واحــدة مــن حبــوب االمفيتامــن بقصــد‬\n      ‫االســتعمال واســتعماله لنوعهــا مــن الســابق ورددت طلــب املدعــي العــام‬\n      ‫اثبــات ادانتــه بشــرب املســكر وحكمــت بعــدم ادانتــه بشــرب املســكر‬\n      ‫ونظــرا لتعــدد ســوابقه وكــون إحداهــا مــن جنــس هــذه الدعــوى وذلــك‬\n      ‫موجــب للتشــديد ولكــون الكميــة املضبوطــة قليلــة جــد ًا وذلــك موجــب‬\n      ‫للتخفيــف فقــد حكمــت عليــه لقــاء احليــازة ولقــاء توجــه التهمــة بحقــه‬\n      ‫بشــرب املســكر بنــاء علــى اإلقــرار املــدون لــدى هيئــة التحقيــق واالدعــاء‬\n            ‫العــام وبنــاء علــى محضــر االستشــمام املشــار إليــه بعاليــه مبــا يلــي‪:‬‬\n      ‫أوال‪ :‬ســجنه ملــدة اربعــة اشــهر تبــدأ مــن تاريــخ ايقافــه املوافــق‬\n      ‫‪1434/2/19‬ه ـ وذلــك بنــاء علــى املــادة (‪)41‬مــن نظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة وإعمــاال للمــادة (‪ )60‬مــن ذات النظــام‪.‬‬\n      ‫ثانيــا‪ :‬جلــده تســعة وســبعني ســوط ًا تعزيــرا علــى دفعتــن األولــى تســعة‬\n      ‫وثالثــن ســوطا والثانيــة أربعــن ســوطا بينهمــا مــاال يقــل عــن عشــرة أيــام‬\n                                 ‫وذلــك لقــاء توجــه التهمــة عليــه بشــرب املســكر‬\n\n\n‫‪165‬‬\n\f‫ثالثــا ‪ :‬منعــه مــن الســفر خــارج اململكــة بعــد انتهــاء محكوميتــه وملــدة‬\n‫ســنتني بنــاء علــى املــادة (‪ )56‬مــن النظــام املشــار إليــه رابعــا‪ :‬صرفــت‬\n‫النظــر عــن طلــب املدعــي العــام إقامــة حــد املســكر عليــه بنــاء علــى مــا‬\n‫ذكــر بعاليــه ‪ .‬وبعــرض احلكــم علــى املدعــى عليــه قــرر قناعتــه به كما‬\n‫قــرر املدعــي العــام االعتــراض علــى احلكــم واكتفــى بالئحــة الدعــوى‬\n‫كالئحــة اعتراضيــة‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                      ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/03/09‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة األولــى‬\n‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة اجلــوف علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بعرعــر برقــم‬\n‫‪ 34565415‬وتاريــخ ‪1434/3/18‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ‪ ..... /‬املســجل برقــم ‪3458980‬‬\n‫وتاريــخ ‪1434/3/9‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد‪..... /‬يف‬\n‫قضيــة مســكر ومخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو‬\n‫مــدون ومفصــل بــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n‫فقــد قررنــا املصادقــة علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                          ‫محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                     ‫‪166‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":161,"source_page_end":166,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"190a3344d24c09487f50f5658d3edd661ff042c5a6eb1b9bffd878e67e89590f","normalized_text_hash":"703c5dd46d5c84154decb446df4390a3141530c9ed68502b57398ae81c666b06","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p161-3458980"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"6a85b2a3-8606-54d6-94fc-3c73e1682c97","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -قيادة سيارة حتت تأثير املسكر -املدعى عليه محكوم عليه باحلد والتعزير بعد واقعة الشرب املدعى بها - تداخل احلدود -تداخل التعازير .","document_number":"34318006","case_number":"33648023","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعنيزة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/9/13","year":"1434","subject":"مسكر -شرب املسكر -قيادة سيارة حتت تأثير املسكر -املدعى عليه محكوم عليه باحلد والتعزير بعد واقعة الشرب املدعى بها - تداخل احلدود -تداخل التعازير .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 34318006 :‬تاريخه‪1434/9/13:‬هـ‬\n                    ‫رقم الدعوى‪33648023:‬‬\n             ‫رقم قرار التصديق من محكمة‬\n‫االستئناف‪ 34333196:‬تاريخه‪1434/10/18:‬هـ‬\n\n\n‫مســكر ‪ -‬شــرب املســكر ‪ -‬قيــادة ســيارة حتــت تأثيــر املســكر ‪ -‬املدعــى‬\n‫عليــه محكــوم عليــه باحلــد والتعزيــر بعــد واقعــة الشــرب املدعــى بهــا ‪-‬‬\n                                      ‫تداخــل احلــدود ‪ -‬تداخــل التعازيــر ‪.‬‬\n\n\n\n\n‫‪ -1‬احلــدود تتداخــل فمــن شــرب اخلمــر مــرارا فــا يحــد ســوى مــرة‬\n‫واحــدة قــال يف شــرح منتهــى اإلرادات ‪ ( 107/11‬حــكاه ابــن املنــذر إجمــاع‬\n‫كل مــن يحفــظ عنــه مــن أهــل العلــم ألن الغــرض الزجــر عــن إتيــان‬\n‫مثــل ذلــك يف املســتقبل وهــو حاصــل بحــد واحــد ) ينظــر مثلــه يف‬\n                                                 ‫كشــاف القنــاع ‪. 412/20‬‬\n                        ‫‪ -2‬التعازير تتداخل انظر كشاف القناع ‪. 485/20‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وقيــادة‬\n‫الســيارة حتــت تأثيره‪،‬وطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بحــد‬\n‫املســكر وعقوبــة تعزيريــة مشــددة لقــاء الســوابق ‪ ،‬حيــث قبــض علــى‬\n‫املدعــى عليــه مــن قبــل الدوريــة األمنيــة بعــد االشــتباه بــه بأنــه بحالــة‬\n‫غيــر طبيعيــة‪ ،‬وباستشــمامه اتضــح أن رائحــة املســكر تفــوح مــن‬\n‫أنفاســه‪،‬وصادق املدعــى عليــه علــى الدعــوى ‪ ،‬وأضــاف بأنــه قــد صــدر‬\n\n                                                                                      ‫‪136‬‬\n\f      ‫عليــه حكــم بحــد املســكر والتعزيــر لتكــرار شــربه بعــد واقعــة شــرب‬\n      ‫املســكر املدعــى بهــا ‪ ،‬وجــرى التخاطــب مــع فضيلــة مصــدر احلكــم‬\n      ‫بشــأن احلكــم الصــادر علــى املدعــى عليــه ‪،‬فتــم تزويــد ناظــر القضيــة‬\n      ‫بصــورة مــن القــرار ‪ ،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة بإثبــات‬\n      ‫إدانــة املدعــى عليــه بشــرب املســكر ‪،‬ورد طلــب املدعــي العــام إقامة حد‬\n      ‫املســكر والتعزيــر اكتفــاء باحلكــم الصــادر علــى املدعــى عليه‪،‬وقنــع‬\n      ‫‪،‬وصــدق احلكــم‬\n                    ‫املدعــى عليــه ‪،‬واعتــرض املدعــي العــام بــدون الئحــة ُ‬\n                                                      ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة العامــة‬\n      ‫بعنيــزة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بعنيــزة برقــم ‪ 33648023‬وتاريــخ ‪1433/11/13‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 331992000‬وتاريــخ ‪1433/11/10‬ه ـ يف يــوم األحد‬\n      ‫املوافق‪1434/01/11‬هـ افتتحت اجللســة الســاعة ‪ 09 : 00‬وفيها حضر‬\n      ‫املدعــي العــام ولــم يحضــر املدعــى عليــه لــذا رفعــت اجللســة ويف جلســة‬\n      ‫أخــرى حضــر املدعــي العــام ‪.....‬وادعــى قائــا بصفتــي مدعي ـ ًا عام ـ ًا يف‬\n      ‫دائــرة التحقيــق واالدعــاء العــام مبحافظــة عنيــزة أدعــي علــى‪،..... -1‬‬\n      ‫البالــغ مــن العمــر (‪ )47‬عامـ ًا ‪ ،‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم (‪ ).....‬متــزوج ‪ ،‬متعلــم ‪ ،‬متســبب‪ ،‬يقيــم يف محافظــة عنيــزة‪ ،‬افــرج‬\n      ‫عنــه بالكفالــة احلضوريــة‪ .‬اســتنادا للمــادة (‪ )120‬مــن نظــام اإلجــراءات‬\n      ‫اجلزائيــة إنــه بتاريــخ ‪1432/8/26‬ه قبــض علــى املدعــى عليــه مــن‬\n      ‫الدوريــات األمنيــة إثــر االشــتباه بــه أنــه بحالــة غيــر طبيعية‪ .‬وباستشــمامه‬\n\n‫‪137‬‬\n\f‫اتضــح أن رائحــة املســكر مــن نــوع كلونيــا تفــوح مــن انفاســه‪ .‬وبتاريــخ‬\n‫‪1433/8/13‬ه قبــض علــى املدعــى عليــه مــن قبــل الدوريــات االمنيــة‬\n‫وهــو يقــود ســيارته وبإســتيقافه بعــد االشــتباه بوضعــه اتضــح أنــه‬\n‫بحالــة غيــر طبيعيــة ‪.‬وباستشــمامه اتضــح انبعــاث رائحــة املســكر مــن‬\n‫نــوع عــرق مــن أنفاســه وباســتجوابه أقــر بشــرب الكلونيــا املســكرة‬\n‫يف القضيــة األولــى ويف القضيــة الثانيــة أقــر بشــرب العــرق املســكر‬\n‫وانتهــى التحقيــق معــه إلــى اتهامــه بشــرب املســكر و قيــادة الســيارة‬\n‫حتــت تأثيــره‪ .‬وذلــك لألدلــة و القرائــن التاليــة ‪-1:‬مــاورد يف أقوالــه‬\n‫املدونــة علــى الصفحــة رقــم (‪ )3.2‬مــن ملــف إجــراءات االســتدالل لفــة‬\n‫(‪ )1‬و الصفحــة (‪ )3‬مــن اللفــة (‪-2.)17‬محضــري القبــض املدونــان علــى‬\n‫اللفــة رقــم (‪-3.)19.3‬محضــري االستشــمام املدونــان علــى ص رقــم (‪)1‬‬\n‫اللفــة (‪ )1‬وص (‪ )2‬مــن اللفــة (‪.)17‬وبالبحــث عمــا إذا كان لــه ســوابق‬\n‫عثــر علــى إحــدى وعشــرين ســابقة منهــا ثمانيــة عشــرة ســابقة شــرب‬\n‫مســكرات‪(.‬مت معاقبتــه علــى قيــادة الســيارة حتــت تأثيــر املســكر‬\n‫مبوجــب خطــاب املــرور رقــم (‪ ).....‬وتاريــخ (‪1433/10/16‬ه) وحيــث إن‬\n‫مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرعا أطلــب أثبــات‬\n‫أدانتــه مبــا أســند إليــه و احلكــم عليــه بحــد شــرب املســكر وبعقوبــة‬\n‫تعزيريــة مشــددة تزجــره و تــردع غيــره لقــاء ســوابقه التــي لــم تردعــه‬\n‫عقوباتهــا هكــذا ادعــى املدعــي العــام وبعــرض دعــواه علــى املدعــى‬\n‫عليــه أجــاب قائــا مــا ذكــره املدعــي العــام يف دعــواه مــن أنــه قبــض‬\n‫علــي بتاريــخ ‪1432/8/26‬ه ـ وتاريــخ ‪1433/8/13‬ه ـ لشــربي املســكر‬\n‫فهــذا كلــه صحيــح وقــد شــربت العــرق املســكر وأنــا تائــب ونــادم وقــد‬\n‫صــدر علــي حكــم بحــد املســكر والتعزيــر لتكــرار شــربه مــن قبــل‬\n\n\n                                                                                  ‫‪138‬‬\n\f      ‫فضيلــة القاضــي بهــذه احملكمــة ‪.....‬واحلكــم صــدر بعــد واقعــة شــربي‬\n      ‫للمســكر املدعــى بهــا لديكــم هكــذا أجــاب املدعــى عليــه وقــد‬\n      ‫جــرى التخاطــب مــع فضيلــة الشــيخ ‪.....‬بشــأن احلكــم الــذي صــدر علــى‬\n      ‫املدعــى عليــه مــن فضيلتــه فزودنــا فضيلتــه بصــورة القــرار الشــرعي رقــم‬\n      ‫‪ 34217680‬يف ‪1434/5/20‬ه ـ الصــادر مــن فضيلتــه بهــذه احملكمــة‬\n      ‫وقــد تضمــن القــرار ادعــاء املدعــي العــام علــى املدعــى عليــه بأنــه شــرب‬\n      ‫املســكر يف ‪1433/11/6‬ه ـ وطلــب املدعــي العــام احلكــم علــى املدعــى‬\n      ‫عليــه بحــد املســكر وتعزيــره لقــاء تكــرار شــربه وقــد أثبــت فضيلتــه‬\n      ‫إدانــة املدعــى عليــه بشــرب املســكر وحكــم عليــه بحــد املســكر‬\n      ‫ثمانــن جلــدة وبتعزيــره لقــاء تكــرار شــرب املســكر بســجنه ملــدة ثــاث‬\n      ‫ســنوات وجلــده أربعمائــة جلــدة مفرقــة وقــد قــرر املدعــي العــام واملدعــى‬\n      ‫عليــه القناعــة انتهــى مضمــون القــرار وأرفقــت صورتــه باملعاملــة وقــد‬\n      ‫ختمــت مبــا يفيــد مطابقتهــا ألصلهــا فبنــاء علــى مــا تقــدم مــن دعــوى‬\n      ‫املدعــي العــام ونظــرا إلــى أن املدعــى عليــه دفــع بأنــه حكــم عليــه بحــد‬\n      ‫املســكر والتعزيــر بعــد واقعــة شــربه للمســكر التــي لدينــا ونظــرا‬\n      ‫إلــى اطالعنــا علــى القــرار الشــرعي املذكــور والــذي يؤيــد مــا دفــع بــه‬\n      ‫املدعــى عليــه حيــث حكــم علــى املدعــى عليــه بحــد املســكر والتعزيــر‬\n      ‫لتكــرار شــربه واحلكــم صــدر بعــد الواقعــة املدعــى بهــا لدينــا ونظــرا‬\n      ‫إلــى أن احلــدود تتداخــل فمــن شــرب اخلمــر مــرارا فــا يحــد ســوى مــرة‬\n      ‫واحــدة قــال يف شــرح منتهــى اإلرادات حــكاه ابــن املنــذر إجمــاع كل‬\n      ‫مــن يحفــظ عنــه مــن أهــل العلــم ألن الغــرض الزجــر عــن إتيــان مثــل‬\n      ‫ذلــك يف املســتقبل وهــو حاصــل بحــد واحــد وكالكفــارات مــن جنــس‬\n      ‫ينظــر شــرح منتهــى اإلرادات ‪ 107/11‬وكشــاف القنــاع ‪ 412/20‬وألن‬\n\n\n‫‪139‬‬\n\f‫التعازيــر تتداخــل ينظــر كشــاف القنــاع ‪ 485/20‬وملــا تقــدم كلــه فقــد‬\n‫ثبــت لــدي إدانــة املدعــى عليــه بشــرب املســكر يف ‪1432/8/26‬ه ـ وثبت‬\n‫لــدي إدانتــه بشــرب املســكر يف ‪1433/8/13‬ه ـ ورددت طلــب املدعــي‬\n‫العــام إقامــة احلــد والتعزيــر علــى املدعــى عليــه اكتفــاء باحلكــم الصــادر‬\n‫علــى املدعــى عليــه مــن فضيلــة الشــيخ القاضــي بهــذه احملكمــة بالقــرار‬\n‫الشــرعي ‪ 34217680‬يف ‪1434/5/20‬ه ـ وبذلــك حكمــت وبعــرض‬\n‫احلكــم علــى املدعــى عليــه قنــع بــه وبعــرض احلكــم علــى املدعــي‬\n‫العــام قــرر عــدم القناعــة وطلــب رفــع احلكــم حملكمــة االســتئناف‬\n‫بــدون الئحــة اعتراضيــة وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                         ‫وصحبــه وســلم حــرر يف ‪1434/09/10‬ه ـ ‪.‬‬\n‫ال ـح ـمـ ــد ل ـلـ ــه وحـ ــده وب ـعـ ــد‪ ...‬ف ـقـ ــد اط ـل ـعـ ــنا ن ـحـ ــن ق ـضـ ــاة الــدائـ ــرة‬\n‫األولـ ــى ل ـتــدق ـيـ ــق ال ـق ـضــايـ ــا ال ـجــزائ ـيـ ــة ب ـم ـح ـك ـمـ ــة االس ـت ـئ ـنـ ــاف‬\n‫ب ـم ـن ـط ـقـ ــة ال ـق ـص ـيـ ــم عـل ــى الـمـع ــاملة الــواردة مــن فضيلــة رئي ـ ــس‬\n‫احملكمــة العامــة مبحافظــة عنيــزة برقــم(‪ )341031616‬وتاريــخ‬\n‫‪1434/9/16‬هــ؛ املقيــدة لدينــا برقــم (‪ )342235288‬وتاريــخ‬\n‫‪1434/9/22‬هــ؛ املرفــق بهــا القــرار رقــم (‪ )34318006‬وتاريــخ‬\n‫‪1434/9/13‬هــ؛ الصــادر مــن فضيلــة الشــيخ‪...../‬القاضي باحملكمــة‬\n‫؛اخلــاص بدعــوى املدعــي العــام ضــد‪ ...../‬التهامــه بشــرب املســكر ‪،‬‬\n‫وقــد تضمــن القــرار حكــم فضيلتــه بســجن وجلــد املدعــى عليــه ‪ ،‬علــى‬\n‫النحــو املفصــل فيــه‪ ،‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n‫‪ ،‬قررنــا املصادقــة علــى احلكــم ‪ ،‬واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                                                            ‫محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n                                                                                                             ‫‪140‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":136,"source_page_end":140,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ce1a316be89eafacdba39f8fb72c6a406fe8c6ae3e621dbe3dc157ceec402783","normalized_text_hash":"2bdc58e1f99308b993cdce82292700b39265fac9fa2714155a4cd7372a5ca543","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p136-34318006"},{"id":"da64904d-90b5-5a37-b844-206c16b3cfda","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -اعتداء على شخص -إمهال املدعي العام أكثر من مرة إلحضار بينته ولم يحضرها -التعزير باجللد يف مكان عام وأخذ التعهد عليه .","document_number":"34365153","case_number":"33659755","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/20","year":"1434","subject":"مسكر -شرب املسكر -اعتداء على شخص -إمهال املدعي العام أكثر من مرة إلحضار بينته ولم يحضرها -التعزير باجللد يف مكان عام وأخذ التعهد عليه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 34365153:‬تاريخه‪1434/11/20:‬هـ‬\n                          ‫رقم الدعوى‪33659755:‬‬\n                   ‫رقم قرار التصديق من محكمة‬\n      ‫االستئناف‪ 35114421:‬تاريخه‪1434/01/14 :‬هـ‬\n\n\n      ‫مســكر ‪ -‬شــرب املســكر ‪ -‬اعتــداء علــى شــخص ‪ -‬إمهــال املدعــي العــام‬\n      ‫أكثــر مــن مــرة إلحضــار بينتــه ولــم يحضرهــا‪ -‬التعزيــر باجللــد يف‬\n                                           ‫مــكان عــام وأخــذ التعهــد عليــه ‪.‬‬\n\n\n\n\n      ‫‪ -1‬قولــه تعالــى ( يأيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب‬\n         ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون ) ‪.‬‬\n       ‫‪ -2‬قوله صلى اهلل عليه وسلم (كل مسكر خمر وكل خمر حرام ) ‪.‬‬\n      ‫‪ -3‬حديــث معاويــة القشــيري أن النبــي صلــى اهلل عليــه وســلم حبــس‬\n      ‫ا يف تهمــة رواه أبــو داود يف ســننه وســكت عنــه وقــال يف رســالته‬     ‫رج ـ ً‬\n      ‫ألهــل مكــة بــأن كل مــا ســكت عنــه فهــو صالــح ورواه الترمــذي يف ســننه‬\n                                                                    ‫وحســنه ‪.‬‬\n                                      ‫‪ -4‬املادة ‪ 122‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر ومهاجمــة أحــد‬\n      ‫األشــخاص وهــو يف حالــة ســكر وطلــب إثبــات مــا أســند إليــه واحلكــم‬\n      ‫عليــه بحــد املســكر وعقوبــة تعزيريــة لقــاء الســوابق ‪ ،‬حيــث قبــض‬\n      ‫علــى املدعــى عليــه مــن قبــل الدوريــات األمنيــة إثــر بــاغ مــن حــارس أمــن‬\n\n‫‪141‬‬\n\f‫بنــك بقيــام املدعــى عليــه بالتهجــم عليــه وهــو يف حالــة ســكر وبانتقــال‬\n‫الدوريــة اتضــح أنــه بحالــة غيــر طبيعيــة وباستشــمامه انبعثــت رائحــة‬\n‫املســكر مــن فمــه ‪،‬صــادق املدعــى عليــه علــى القبــض عليــه وأنكــر‬\n‫تعاطــي املســكر وأن التهمــة لُبســت لــه ملشــاجرته أحــد األشــخاص ‪،‬‬\n‫وحيــث إن بينــة املدعــي العــام محضــر االستشــمام فقــد أمهلته احملكمة‬\n‫عــدة جلســات إلحضــار البينــة ولــم يحضرهــا فجــرى إفهامــه بأنــه ال‬\n‫مهلــة لــه بنــاء علــى املــادة ‪ 122‬مــن نظــام املرافعــات الشــرعية ‪،‬وحيــث‬\n‫إن املدعــى عليــه أنكــر شــرب املســكر ومبــا أنــه ال بينــة للمدعــي‬\n‫العــام ســوى محضــر االستشــمام وكثــرة الســوابق وذلــك يوجــه التهمــة‬\n‫القويــة وال يرقــى إلثبــات اإلدانــة ‪،‬صــرف النظــر عــن طلــب املدعــي العــام‬\n‫بإثبــات شــرب املدعــى عليــه للمســكر وإقامــة حــد املســكر وحكمــت‬\n‫احملكمــة عليــه بجلــده خمســن جلــدة تعزيــر ًا وأخــذ التعهد عليــه بالبعد‬\n‫عــن مواطــن الشــبهة وعــدم تكــرار ذلــك وقنــع املدعــى عليــه واعتــرض‬\n               ‫‪،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬    ‫املدعــي العــام ُ‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم ‪33659755‬‬\n‫وتاريــخ ‪1433/11/17‬ه ـ املقيــدة باحملكمــة برقــم ‪332043145‬‬\n‫وتاريــخ ‪1433/11/17‬ه ـ ففــي يــوم األربعــاء املوافــق‪1433/11/17‬‬\n‫ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 15‬وفيهــا حضــر املدعــي العــام ‪.....‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬املكلــف مبوجــب‬\n\n                                                                                    ‫‪142‬‬\n\f      ‫اخلطــاب رقــم ‪.....‬يف ‪1432/01/16‬ه ـ الصــادر مــن رئيــس دائــرة االدعــاء‬\n      ‫ا بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة‬    ‫العــام مبحافظــة جــدة وادعــى قائ ـ ً‬\n      ‫االدعــاء العــام مبحافظــة جــدة أدعــي ‪ 43 .....‬عام ـ ًا ســعودي اجلنســية‬\n      ‫يحمــل الســجل املدنــي رقــم (‪ ).....‬املقــدم للمحاكمــة رفــق الئحــة‬\n      ‫الدعــوى بشــربه املســكر ألنــه بتاريــخ ‪1433/11/14‬ه ـ مت القبــض‬\n      ‫علــى املدعــى عليــه مــن قبــل الدوريــات األمنيــة أثــر بــاغ مــن حــارس‬\n      ‫األمــن يف البنــك األهلــي الواقــع بحــي ‪.....‬املدعــو ‪..... /‬بقيــام املدعــى‬\n      ‫عليــه بالتهجــم عليــة وهــو يف حالــة ســكر وبانتقــال الدوريــة اتضــح انــه‬\n      ‫يف حالــة غيــر طبيعيــة وباستشــمامه انبعثــت رائحــة املســكر مــن فمــه‬\n      ‫وقــد خلــص التحقيــق معــه إلــى توجيــه االتهــام لــه مبــا اســند إليــه وذلــك‬\n      ‫لألدلــة والقرائــن املرصــودة يف ملــف الدعــوى وبالبحــث عــن ســوابق‬\n      ‫عثــر لــه علــى اثنــي عشــر ســابقة (تســع ســوابق منهــا ســكر حــد يف‬\n      ‫ثمــان منهــا إحداهــا مقترنــة بخطــف وفعــل فاحشــة اللــواط وأخــري‬\n      ‫بالنهــب وثالثــة مقترنــة بقيــادة ســيارة وهــو يف حالــة ســكر ومخــدرات‬\n      ‫وســابقة اعتــداء وســرقة ســيارات وســابقة اشــتباه نهــب وســابقة دخــول‬\n      ‫منــزل لغــرض ســيء) وحيــث أن مــا أقــدم عليــه املذكــور فعــل محرمــا‬\n      ‫معاقبــا عليــه شــرعا لــذا فإننــي أطلــب اثبــات مــا أســند إليــه واحلكــم‬\n      ‫عليــه بحــد املســكر وبعقوبــة تعزيزيــة مشــددة ورادعــة لتعــدد ســوابقه‬\n      ‫يف شــرب املســكرات وعــدم ارتداعــه مــن الســابق اســتنادا لقــرار هيئــة‬\n      ‫كبــار العلمــاء رقــم (‪ )53‬وتاريــخ ‪1397/4/4‬ه ـ هكــذا ادعــى وبســؤال‬\n      ‫ا مــا ذكــره املدعــي العــام مــن مــكان القبــض‬      ‫املدعــى عليــه أجــاب قائـ ً‬\n      ‫وتاريخــه فهــو صحيــح وأمــا مــا ذكــره بخصــوص أنــي أتعاطــي املســكر‬\n      ‫فهــو غيــر صحيــح وأنــا لــم أشــرب املســكر وكل مــا يف األمــر أنــي‬\n\n\n‫‪143‬‬\n\f‫تشــاجرت مــع أحــد األشــخاص وأبلــغ عنــي مركــز الشــرطة وألبســني‬\n‫تهمــة شــرب املســكر ولــم يجــدوا معــي مســكر وليــس هنــاك محضــر‬\n‫استشــمام وعلــي اثنــي عشــرة ســابقة وقــد تبــت مــن ذلــك وهلل احلمــد‬\n‫ا أطلــب‬    ‫هكــذا أجــاب وبســؤال املدعــي العــام عــن البينــة أجــاب قائ ـ ً‬\n‫املهلــة إلحضارهــا ويف جلســة أخــرى افتتحــت اجللســة يــوم اخلميــس‬\n‫املوافــق ‪1434/11/06‬ه ـ الســاعة ‪ 10:00‬وحضــر فيهــا املدعــي العــام‬\n‫واملدعــى عليــه وبســؤال املدعــي العــام هــل أحضــرت البينــة علــى دعــواك‬\n‫التــي أمهلــت مــن أجلهــا قــال ال واطلــب املهلــة إلحضارهــا فأفهمتــه أنــه ال‬\n‫مهلــة لــه بنــاء علــى املــادة (‪ )122‬مــن نظــام املرافعــات الشــرعية ولوائحــه‬\n‫التنفيذيــة ألنــه أمهــل ثــاث مــرات بنــاء علــى الطلــب األول برقــم ‪.....‬يف‬\n‫‪1433/11/22‬ه ـ والطلــب الثانــي برقــم ‪.....‬يف ‪1434/1/12‬ه ـ والطلــب‬\n‫الثالــث برقــم ‪.....‬يف ‪1434/2/19‬ه ـ هــذا وقــد جرى االطــاع على أوراق‬\n‫املعاملــة ومــا جــاء فيهــا فوجــدت محضــر استشــمام علــى اللفــة رقــم ‪12‬‬\n‫صفحــة رقــم ‪ 2‬وهــو يفيــد التهمــة ومــا جــاء يف دفتــر التحقيــق مــن أقــوال‬\n‫للمدعــى عليــه مطابــق إلنــكاره يف مجلــس احلكــم فبنــاء علــى مــا تقــدم‬\n‫مــن الدعــوى وجوابهــا ومــا قــرره الطرفــان وحيــث أنكــر املدعــى عليــه‬\n‫شــربه املســكر وحيازتــه وال بينــة للمدعــى العــام ســوى مــا جــاء يف‬\n‫محضــر االستشــمام وكثــرة الســوابق وكل ذلــك يــورث التهمــة القويــة‬\n‫وال يرقــي إلــى إثبــات اإلدانــة ولقولــه تعالــى‪ (:‬يــا أيهــا الذيــن آمنــوا إمنــا‬\n‫اخلمــر وامليســر واألنصــاب واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه‬\n‫لعلكــم تفلحــون ) ولقولــه صلــى اهلل عليــه وســلم ( كل مســكر خمــر‬\n‫وكل خمــر حــرام) رواه مســلم وألنــه مــن أربــاب الســوابق وملــا جــاء يف‬\n‫ا‬\n‫حديــث معاويــة القشــيري أن النبــي صلــى اهلل عليــه وســلم حبــس رجـ ً‬\n\n\n                                                                                           ‫‪144‬‬\n\f      ‫يف تهمــة رواه ابــو داود يف ســننه وســكت عنــه وقــال يف رســالته ألهــل‬\n      ‫مكــة بــأن كل مــا ســكت عنــه فهــو صالــح ورواه الترمــذي يف ســننه‬\n      ‫وحســن ولــكل مــا تقــدم فقــد صرفــت النظــر عــن طلــب املدعــى العــام‬\n      ‫بإثبــات إدانــة املدعــى عليــه بشــرب املســكر وإقامــة حــد املســكر لعــدم‬\n      ‫البينــة الكافيــة وحكمــت علــى املدعــى عليــه ‪ .....‬لقــاء التهمــة مبــا يلــي‬\n                                 ‫أوالً‪ :‬جلده خمسني جلدة دفعة واحدة علن ًا تعزير ًا‬\n                ‫ثانياً‪ :‬أخذ التعهد بالبعد عن مواطن الشبهة وعدم تكرار ذلك‬\n      ‫وبعــرض احلكــم علــى املدعــى عليــه قــرر القناعــة واملدعــي العــام قــرر‬\n      ‫عــدم القناعــة وأف ِهــم بــأن عليــه تقــدمي الئحــة اعتراضيــة خــال مــدة‬\n      ‫ثالثــن يومـ ًا مــن اســتالم نســخة احلكــم خــال عشــره أيــام وإال ســقط‬\n      ‫حقــه يف االعتــراض وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                         ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/11/06‬ه ـ‬\n                  ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده وبعد ‪:‬‬\n      ‫نحــن قضــاة الدائــرة اجلزائيــة السادســة مبحكمــة االســتئناف مبكــة‬\n      ‫املكرمــة جــرى منــا االطــاع علــى املعاملــة الــواردة إلــى هــذه احملكمــة‬\n      ‫بكتــاب فضيلــة رئيــس احملكمــة اجلزائيــة بجــدة رقــم(‪)33/2043145‬‬\n      ‫وتاريخ(‪1435/1/7‬هــ) املرفــق بهــا القــرار رقــم(‪)34365153‬‬\n      ‫وتاريخ(‪1434/11/20‬هـ)الصــادر مــن فضيلــة الشــيخ‪...../‬القاضي‬\n      ‫باحملكمــة اجلزائيــة بجــدة‪ ،‬املتضمــن دعــوى املدعــي العــام ضــد‪...../‬‬\n      ‫ســعودي اجلنســية ‪ ،‬املتهــم بشــرب املســكر ‪ ،‬احملكــوم فيــه مبــا دون‬\n      ‫باطنــه ‪ ،‬وبدراســة القــرار وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت‬\n      ‫املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                                                        ‫وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n‫‪145‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":141,"source_page_end":145,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b3136ee210f13ce05d7d814c025a62491ce0e7062558eacbed7c849e3ad604b3","normalized_text_hash":"66d310d0e68436a04d81665d82ea15022197e2854c5241c913ef32b5a77a9b50","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p141-34365153"},{"id":"3131bede-ce30-55d4-8026-9b51471618e7","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -حد املسكر -حيازته بقصد الشرب -تعزير بالسجن واجللد للشبهة وللسوابق .","document_number":"3418756","case_number":"33670840","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/20","year":"1434","subject":"مسكر -شرب املسكر -حد املسكر -حيازته بقصد الشرب -تعزير بالسجن واجللد للشبهة وللسوابق .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك‪ 3418756:‬تاريخه‪1434/1/20:‬هـ‬\n                  ‫رقم الدعوى‪33670840:‬‬\n            ‫رقم قرار التصديق من محكمة‬\n‫االستئناف‪ 3439059:‬تاريخه‪1434/02/17 :‬هـ‬\n\n\n‫مســكر ‪ -‬شــرب املســكر ‪ -‬حــد املســكر ‪ -‬حيازتــه بقصــد الشــرب ‪ -‬تعزيــر‬\n                                   ‫بالســجن واجللــد للشــبهة وللســوابق ‪.‬‬\n\n\n\n\n‫‪ -1‬قولــه صلــى اهلل عليــه وســلم ( مــن شــرب اخلمــر فاجلــدوه ) رواه‬\n                                          ‫أحمــد وأبــو داود والنســائي ‪.‬‬\n‫‪ -2‬إجمــاع الصحابــة علــى جلــد شــارب اخلمــر ثمانــن جلــده وهــو‬\n     ‫املذهــب وعليــه جماهيــر األصحــاب (كشــاف القنــاع ‪)99/14‬‬\n                                                  ‫و( االنصاف ‪.)441/15‬‬\n            ‫‪ -3‬قرار هيئة كبار العلماء رقم (‪ )53‬بتاريخ ‪1397/4/4‬هـ ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وحيازتــه‬\n‫بقصــد الشــرب ‪ ،‬وطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بحــد‬\n‫املســكر وتعزيــره للســوابق وحيــازة املســكر ‪ ،‬حيــث قبــض علــى‬\n‫املدعــى عليــه مــن قبــل الدوريــات األمنيــة وقــد كان مســتلقي ًا علــى‬\n‫األرض وبحوزتــه قــارورة حتتــوي علــى مــادة بيضــاء ‪،‬وباستشــمامه تبــن‬\n‫انبعــاث رائحــة املســكر منــه ‪،‬وأقــر املدعــى عليــه بالشــرب وأنكــر‬\n‫احليــازة ‪،‬ومبــا أن املدعــى عليــه أقــر بشــرب املســكر ‪،‬وبنــاء علــى مــا‬\n\n                                                                                 ‫‪146‬‬\n\f      ‫تقــدم حكمــت احملكمــة بجلــده ثمانــن جلــده دفعــه واحــدة يف مــكان‬\n      ‫عــام حــد املســكر ‪،‬وعــدم ثبــوت إدانــة املدعــى عليــه بحيــازة املســكر‬\n      ‫وتعزيــره بالســجن ســبعة أشــهر وجلــده مائتــي جلــده مفرقــة علــى دفعــات‬\n      ‫متســاوية لقــاء شــبهة احليــازة وتكــرار الســوابق ‪،‬وقنــع املدعــى عليــه‬\n      ‫وصــدق احلكــم مــن‬ ‫باحلكــم واعتــرض املدعــي العــام بــدون الئحــة ‪ُ ،‬‬\n                                                           ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n      ‫أنــا ‪ .....‬القاضــي باحملكمــة اجلزائيــة بالدمــام بنــاء علــى املعاملــة الــواردة‬\n      ‫مــن هيئــة التحقيــق واالدعــاء العــام واملقيــدة لــدى احملكمــة برقــم‬\n      ‫‪ 332089831‬وتاريــخ ‪1433/11/22‬ه ـ واحملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة بالدمــام برقــم ‪ 33670840‬وتاريــخ ‪1433/11/22‬هـ‬\n      ‫افتتحــت اجللســة يف يــوم الثالثــاء ‪1434/1/20‬ه ـ الســاعة التاســعة‬\n      ‫ا فيهــا‬\n             ‫وخمســة وأربعــن دقيقــة وفيهــا قــدم املدعــي العــام ‪ .....‬دعــواه قائـ ً‬\n      ‫بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة االدعــاء العــام لفــرع املنطقــة الشــرقية‬\n      ‫أدعــي علــى‪..... /‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬‬\n      ‫حيــث إنــه باالطــاع علــى محضــر االنتقــال والقبــض والتفتيــش املعــد‬\n      ‫مــن الدوريــات األمنيــة بالدمــام بتاريــخ يــوم االثنــن ‪1433/10/23‬ه ـ‬\n      ‫تبــن أنــه مت القبــض علــى املدعــى عليــه اثــر ورود بــاغ للعمليــات مــن‬\n      ‫العثــور عليــه ملقــى علــى األرض يف داخــل الســوق وعنــد الوصــول إليــه‬\n      ‫تبــن أنــه بحالــة ســكر ومت العثــور بحوزتــه علــى قــارورة مــاء صحــة‬\n      ‫صغيــرة حتتــوي علــى مــادة شــفافة بيضــاء اللــون مت بعثهــا للمركــز‬\n\n‫‪147‬‬\n\f‫اإلقليمــي للســموم لفحصهــا وباستشــمامه تبــن انبعــاث رائحــه املســكر‬\n‫منــه وبســماع أقوالــه أقــر بشــربه للمســكر وأنكــر حيازتــه ملــا مت‬\n‫ضبطــه مــن املســكر بحوزتــه وقــد انتهــى التحقيــق إلــى اتهــام‪..... /‬‬\n‫باآلتــي‪ -1 :‬بشــرب املســكر ‪ -2‬بحيازتــه لقــارورة حتتــوي علــى املــادة‬\n‫املســكرة بقصــد الشــرب وذلــك لألدلــة والقرائــن التاليــة ‪ -1:‬مــا ورد‬\n‫يف أقوالــه املنــوه عنهــا علــى الصفحــة رقــم (‪ )10-9‬مــن ملــف التحقيــق‬\n‫علــى اللفــة رقــم (‪ -2 )1‬محضــر االنتقــال والقبــض والتفتيــش املنــوه عنــه‬\n‫علــى اللفــة رقــم (‪ -3 )2‬محضــر االستشــمام املنــوه عنــه علــى الصفحــة‬\n‫رقــم (‪ )6‬مــن ملــف التحقيــق علــى اللفــة رقــم (‪ )1‬وباحلــث عــن ســوابقه‬\n‫عثــر لــه علــى أربــع ســوابق ثــاث شــرب مســكر والرابعــة اشــتباه ســكر‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرعا‬\n‫فعــل محــرم ومعاقــب عليــه شــرعا أطلــب اثبــات مــا أســند إليــه واحلكــم‬\n‫عليــه باالتــي‪ -1:‬حــد املســكر لقــاء شــربه للمســكر واحلكــم عليــه‬\n‫بعقوبــة تعزيريــة وفــق قــرار هيئــة كبــار العلمــاء رقــم ( ‪ ) 53‬وتاريــخ‬\n‫‪1397/4/4‬ه ـ لقــاء تعــدد ســوابق شــرب املســكر احلديــة ‪-2‬احلكــم‬\n‫عليــه بعقوبــة تعزيريــة لقــاء حيازتــه لقــارورة حتتــوي على املادة املســكرة‬\n‫بقصــد الشــرب هكــذا ادعــى وبعــرض دعــوى املدعي العــام على املدعى‬\n‫ا مــا ذكــره املدعــي العــام مــن شــربي للمســكر فذلــك‬     ‫عليــه أجــاب قائـ ً‬\n‫صحيــح وأمــا حيــازة املســكر فغيــر صحيحــة والســوابق ال أذكــر منهــا‬\n‫إال اثنتــان فقــط وهمــا شــرب مســكر هكــذا أجــاب وبعــرض ذلــك على‬\n‫املدعــي العــام قــال مــا ذكــره املدعــى عليــه مــن عــدم حيازتــه للمســكر‬\n‫وأن الســوابق اثنتــان فذلــك غيــر صحيــح والصحيــح مــا ذكرتــه يف‬\n‫دعــواي هكــذا أجــاب ثــم جــرى ســؤال املدعــي العــام البينــة علــى دعــواه‬\n\n\n                                                                                      ‫‪148‬‬\n\f      ‫فقــال أطلــب الرجــوع إلــى املعاملــة هكــذا أجــاب ثــم جــرى الرجــوع إلــى‬\n      ‫املعاملــة فوجــدت علــى لفــة رقــم (‪ )1‬دفتــر التحقيــق ص (‪ )6‬محضــر‬\n      ‫استشــمام املتضمــن انبعــاث رائحــة املســكر مــن أنفــاس املدعــى عليــه‬\n      ‫كمــا وجــدت علــى لفــة رقــم (‪ )2‬محضــر تنفيــذ مهمــة املتضمــن طبــق مــا‬\n      ‫ذكــره املدعــي العــام يف دعــواه كمــا وجــدت علــى لفــة رقــم (‪ )13‬قــرار‬\n      ‫اتهــام املتضمــن وجــود أربــع ســوابق للمدعــى عليــه ثــاث شــرب مســكر‬\n      ‫ـاء علــى مــا تقــدم مــن دعــوى املدعــي العــام‬\n                                                      ‫والرابعــة اشــتباه ســكر فبنـ ً‬\n      ‫وإجابــة املدعــى عليــه وإقــرار بشــرب املســكر ووجــود ســابقتني شــرب‬\n      ‫مســكر وهــو بكامــل أهليتــه املعتبــرة شــرع ًا ولقولــه صلــى اهلل عليــه‬\n      ‫وســلم (مــن شــرب اخلمــر فاجلــدوه) رواه أحمــد وأبــو داود والنســائي‬\n      ‫كمــا انعقــد إجمــاع الصحابــة رضــي اهلل عنهــم علــى جلــد شــارب اخلمــر‬\n      ‫ثمانــون جلــدة (كشــاف القنــاع عــن اإلقنــاع ‪ )99/14‬وهــو املذهــب‬\n      ‫وعليــه جماهيــر األصحــاب (اإلنصــاف ‪ )441/15‬ونظــر ًا لعــدم اكتمــال‬\n      ‫البينــة علــى حيــازة املدعــى عليــه للمســكر ونظــر ًا لوجــود ســوابق شــرب‬\n      ‫ـاء علــى قــرار‬\n                     ‫مســكر للمدعــى عليــه لــم تردعــه عقوباتهــا الســابقة وبنـ ً‬\n      ‫هيئــة كبــار العلمــاء رقــم ( ‪ ) 53‬وتاريــخ ‪1397/4/4‬ه ـ لــذا كلــه فقــد‬\n      ‫ثبــت لــدي إدانــة املدعــى عليــه بشــرب اخلمــر املســكر ولــم تثبــت لــدي‬\n      ‫إدانتــه بحيازتــه للمســكر وقــررت اآلتــي‪ :‬أوالً‪ :‬جلــده ثمانــن جلــدة دفعة‬\n      ‫واحــدة حــد املســكر ويكــون التنفيــذ يف مــكان عــام يحضــره جمــع‬\n      ‫مــن النــاس‪ .‬ثاني ـاً‪ :‬ســجنه ملــدة ســبعة أشــهر حتتســب منهــا مــدة إيقافــه‬\n      ‫وجلــدة مائتــن جلــدة تعزيــر ًا مفرقــة علــى دفعــات متســاوية بــن كل‬\n      ‫دفعــة وأخــرى مــدة ال تقــل عــن عشــرة أيــام وذلــك لقــاء شــبهة حيــازة‬\n      ‫املســكر وتكــرار الســوابق علــى أن يكــون بــن تنفيــذ احلــد والتعزيــر‬\n\n\n‫‪149‬‬\n\f‫مــدة ال تقــل عــن عشــرة أيــام وبــكل مــا تقــدم حكمــت وبعــرض احلكــم‬\n‫علــى الطرفــن قــرر املدعــى عليــه القناعــة باحلكــم كمــا قــرر املدعــي‬\n‫العــام االعتــراض بــدون الئحــة اعتراضيــة وبــاهلل التوفيــق وصلــى اهلل‬\n                            ‫وســلم علــى نبينــا محمــد‪ .‬حــرر يف ‪1434/1/20‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة‬\n‫املقيــدة لــدى احملكمــة برقــم ‪/34343619‬ج‪ 2‬وتاريــخ ‪1434/2/11‬ه ـ‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبدينــة الدمــام برقــم‬\n‫‪ 33/2089831‬وتاريــخ ‪1434/2/5‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ ‪...../‬املســجل برقــم ‪3418756‬‬\n‫وتاريــخ ‪1434/1/20‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪........../‬يف‬\n‫قضيــة مســكر وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n‫املصادقــة علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                    ‫وصحبــه وســلم‪ .‬حــرر يف‪1434/2/17‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                         ‫‪150‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":146,"source_page_end":150,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"18be2091bde5653f651c563bf6c9fe3e3a0c585d5d7b594a28ab14fc729afec3","normalized_text_hash":"29efebf82920a4f1fc9afce82ba4e14102b66b2a74afcb1747c3e5a323d228c3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p146-3418756"},{"id":"d7a9689c-aafe-52dc-a6e9-970b342ad7d0","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -حيازة بقصد االستعمال -مصادقة على الدعوى -إقامة حد املسكر -التعزير بالسجن على احليازة -أخذ التعهد عليه بعدم العودة .","document_number":"33468786","case_number":"33673241","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/17","year":"1434","subject":"مسكر -شرب املسكر -حيازة بقصد االستعمال -مصادقة على الدعوى -إقامة حد املسكر -التعزير بالسجن على احليازة -أخذ التعهد عليه بعدم العودة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك ‪ 33468786‬تاريخه‪1434/1/17:‬هـ‬\n                        ‫رقم الدعوى‪33673241:‬‬\n                   ‫رقم قرار التصديق من محكمة‬\n        ‫االستئناف‪ 3425079:‬تاريخه‪1434/01/27:‬هـ‬\n\n\n      ‫مســكر ‪ -‬شــرب املســكر ‪ -‬حيــازة بقصــد االســتعمال ‪ -‬مصادقــة علــى‬\n      ‫الدعــوى ‪ -‬إقامــة حــد املســكر ‪ -‬التعزيــر بالســجن علــى احليــازة ‪ -‬أخــذ‬\n                                                   ‫التعهــد عليــه بعــدم العــودة ‪.‬‬\n\n\n\n\n      ‫‪ -1‬قــال تعالــى (يأيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب‬\n         ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون ) ‪.‬‬\n      ‫‪ -2‬مــا أخرجــه أبــوداود عــن ابــن عمــر رضــي اهلل عنهمــا أنــه صلــى‬\n      ‫اهلل عليــه وســلم قــال ( لعــن اهلل اخلمــر وشــاربها وبائعهــا ومبتاعهــا‬\n                      ‫وعاصرهــا ومعتصرهــا وحاملهــا واحملمولــة إليــه ) ‪.‬‬\n      ‫‪ -3‬قــرار هيئــة كبــار العلمــاء ‪ 53‬يف ‪1397/4/4‬ه ـ مــن أن عقوبــة شــارب‬\n      ‫اخلمــر احلــد ال التعزيــر وأن مقــداره ثمانــون جلــده يتــم تنفيــذه جملــة‬\n                                                                           ‫واحــدة ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وحيازتــه وطلب‬\n      ‫إثبــات مــا أســند إليــه واحلكــم عليــه باملقتضــى الشــرعي والتشــديد‬\n      ‫عليــه لتعــدد ســوابقه ‪،‬حيــث قبــض علــى املدعــى عليــه مــن قبــل الدوريــة‬\n      ‫األمنيــة داخــل مســبح وهــو يف حالــة غيــر طبيعيــة ومت تفتيــش ســيارته‬\n\n‫‪151‬‬\n\f‫وعثــر بهــا علــى دبــة صغيــرة بهــا مــادة غيــر معروفــة وباستشــمامها اتضــح‬\n‫أنهــا مــادة العــرق املســكر ‪،‬وصــادق املدعــى عليــه علــى دعــوى املدعــي‬\n‫‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة عليــه بحــد املســكر بجلــده‬\n‫ثمانــن جلــده دفعــة واحــدة علن ـ ًا يف مــكان عــام وتعزيــره بســجنه ســنة‬\n‫واحــدة لقــاء احليــازة وأخــذ التعهــد عليــه بعــدم العــودة ملثــل مــا بــدر منــه‬\n‫وصــدق احلكــم مــن‬    ‫‪،‬قنــع املدعــي العــام واعتــرض املدعــى عليــه بالئحــة ُ‬\n                                                            ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنا‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بنجــران وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بنجــران برقــم ‪ 33673241‬وتاريــخ ‪ 1433/11/23‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 332100533‬وتاريــخ ‪ 1433/11/23‬ه ـ ففــي يــوم‬\n‫األربعــاء املوافــق‪ 1433/11/24‬ه ـ افتتحــت اجللســة الســاعة ‪: 45‬‬\n‫‪ 11‬بشــأن دعــوى املدعــي العــام ‪.....‬واملكلــف مبهمــة اإلشــراف علــى‬\n‫مكتــب االدعــاء العــام مبحاكــم جنــران مبوجــب خطــاب رئيــس‬\n‫فــرع هيئــة التحقيــق واالدعــاء العــام مبنطقــة جنــران رقــم ‪.....‬وتاريــخ‬\n‫‪1430/12/29‬ه ـ ضــد ‪..... /‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة‬\n‫ا يف دعــواه عليــه إنــه ورد يف محضــر دوريــات األمنيــة رقــم‬ ‫رقــم ‪.....‬قائـ ً‬\n‫‪.....‬وتاريــخ ‪1432/12/27‬ه ـ أنهــا تلقــت بــاغ عــن طريــق غرفــة العمليات‬\n‫يفيــد عــن وجــود مبلــغ يف فنــدق األخــدود ومت االنتقــال إلــى الفنــدق‬\n‫ووجــد املبلــغ وأفــاد عــن وجــود شــخص داخــل املســبح ويشــتبه أنــه يف‬\n‫حالــة غيــر طبيعــة ويصــدر منــه أصــوات داخــل املســبح فتــم القبــض عليــه‬\n\n                                                                                          ‫‪152‬‬\n\f      ‫وكان داخــل املســبح ويشــتبه أنــه يف حالــة غيــر طبيعيــة وقــد مت تفتيــش‬\n      ‫الســيارة وعثــر علــى دبــة صغيــرة يوجــد بهــا أقــل مــن النصــف مــادة‬\n      ‫غيــر معروفــه وقــد مت إركاب الشــخص يف الدوريــة فقــام بتكســير‬\n      ‫البالســتيك الداخلــي للبــاب اخللفــي للدوريــة وقــد ســلم الشــخص إلــى‬\n      ‫مركــز شــرطة الفيصليــة إلكمــال الــازم كمــا جــرى االطــاع علــى‬\n      ‫محضــر االستشــمام املــؤرخ يف ‪1432/12/27‬ه ـ املعــد مــن قبــل عضــو‬\n      ‫هيئــة األمــر باملعــروف والنهــي عــن النكــر وضابــط مركــز شــرطة‬\n      ‫الفيصليــة املتضمــن ( أنهــم لــم يســتطيعوا االقتــراب مــن املذكــور ألنــه‬\n      ‫كان يف حالــة هيجــان ويهــذي بأصــوات عاليــة ويتصــرف بتصرفــات‬\n      ‫غيــر طبيعيــة ممــا يــدل علــى أنــه يف حالــة غيــر طبيعيــة وباستشــمام‬\n      ‫املــادة املضبوطــة معــه يف الســيارة اتضــح أنهــا مــادة العــرق املســكرة‬\n      ‫وباســتجواب املدعــى عليــه أقــر بقيامــه بشــرب كأســن مــن املــادة‬\n      ‫املســكرة كمــا أقــر بــأن مــا مت ضبطــه داخــل ســيارته باقــي املــادة‬\n      ‫املســكرة وقــد انتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه‬\n      ‫بشــرب مــادة العــرق املســكر وحيازتــه وذلــك لألدلــة والقرائــن التاليــة‬\n      ‫‪ -1:‬مــا جــاء يف اعترافــه املصــدق شــرع ًا واملــدون علــى ص رقــم (‪ )7‬لفــه‬\n      ‫رقــم (‪ -2 )1‬مــا جــاء يف محضــر القبــض املعــد مــن قبــل الدوريــة األمنيــة‬\n      ‫لفــه رقــم (‪ -3 )3‬مــا جــاء يف محضــر االستشــمام واملــدون علــى ص‬\n      ‫رقــم (‪ )3‬مــن ملــف التحقيــق املرفــق لفــه رقــم (‪ )1‬وبالبحــث عــن ســوابق‬\n      ‫املدعــى عليــه عثــر لــه علــى ســت ســوابق األولــى ســرقة مســاكن والثانيــة‬\n      ‫مضاربــة داخــل الســجن والثالثــة مقاومــة رجــال األمــن مضاربــة اشــتباه‬\n      ‫مســكر والرابعــة شــرب املســكرات اخلامســة اســتعمال املخــدرات‬\n      ‫السادســة شــرب املســكرات وتأسيس ـ ًا علــى مــا ســبق وألن مــا أقــدم‬\n\n\n‫‪153‬‬\n\f‫ا محرمـ ًا‬ ‫عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرع ًا يعــد فعـ ً‬\n‫معاقب ـ ًا عليــه شــرع ًا لــذا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم‬\n‫عليــه باملقتضــى الشــرعي والتشــديد عليــه نظــر ًا لتعــدد ســوابقه ولوجــود‬\n‫ثــاث ســوابق مــن جنــس القضيــة احلاليــة وبــاهلل التوفيــق هــذه دعــواي‬\n‫وبعــرض الدعــوى علــى املدعــى عليــه قــال مــا ذكــره املدعــي العــام مــن‬\n‫قيامــي بشــرب مــادة العــرق املســكرة وحيازتهــا بقصــد التعاطــي فهــو‬\n‫صحيــح جملــة وتفصيــا هكــذا أجــاب وللتأمــل ودراســة القضيــة رفعــت‬\n‫اجللســة إلــى يــوم الســبت املوافــق ‪1433/11/27‬ه ـ الســاعة العاشــرة‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n‫وســلم ‪ .‬حــرر يف ‪ 1433/11/24‬ه ـ الســاعة ‪ 12:00‬احلمــد هلل وحــده‬\n‫وبعــد فلــدي ففــي يــوم الســبت املوافــق‪ 1433/11/27‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 12:00‬وفيها حضر املدعى عليه و بعد التأمل والدراســة وبناء‬\n‫علــى مــا ســبق مــن الدعــوى واإلجابــة وحيــث إن املدعــى عليــه قــد اعتــرف‬\n‫بقيامــه بشــرب العــرق املســكر وحيازتــه بقصــد التعاطــي و ملــا كان‬\n‫شــرب العــرق املســكر وحيازتــه أمــر ًا محرم ـ ًا يف الشــريعة اإلســامية‬\n‫بدليــل قولــه تعالــى‪« :‬يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب‬\n       ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون»‬\n‫( املائدة ‪ ) 90 :‬و ما أخرجه أبو داود عن ابن عمر رضي اهلل عنهما أنه‬\n‫قــال ‪ :‬قــال رســول اهلل صلــى اهلل عليــه وســلم‪ « :‬لعــن اهلل اخلمــر وشــاربها‬\n‫وســاقيها وبائعهــا و مبتاعهــا وعاصرهــا ومعتصرهــا وحاملهــا واحملمولــة‬\n‫إليــه « ( كتــاب األشــربة ‪ ،‬البــاب ‪ :‬العنــب يعصــر للخمــر ‪ ،‬احلديــث رقــم‬\n‫‪ )3189‬واســتناد ًا علــى مــا تضمنــه قــرار هيئــة كبــار العلمــاء رقــم ‪53‬‬\n‫وتاريــخ ‪1397/4/4‬ه ـ مــن أن عقوبــة شــارب اخلمــر احلــد ال التعزيــر وأن‬\n\n\n                                                                                           ‫‪154‬‬\n\f      ‫مقــداره ثمانــون جلــدة يتــم تنفيــذه جملــة واحــدة و نظــر ًا إلــى أن املدعــى‬\n      ‫عليــه مــن أربــاب الســوابق يف حيــازة املخــدرات واســتعمالها وشــرب‬\n      ‫املســكرات ممــا يــدل علــى عــدم ارتداعــه مــن األحــكام الســابقة ولقلــة‬\n      ‫الكميــة املضبوطــة وتأسيس ـ ًا علــى جميــع مــا تقــدم فقــد قــررت مــا‬\n      ‫يأتــي أو ًال ‪ :‬ثبــت لــدي إدانــة املدعــى عليــه بقيامــه بشــرب مــادة العــرق‬\n      ‫املســكرة وحيازتهــا بقصــد التعاطــي ثاني ـ ًا ‪ :‬معاقبتــه بحــد املســكر‬\n      ‫وذلــك بجلــده ثمانــن جلــدة دفعــة واحــدة علن ـ ًا يف مــكان عــام ثالث ـ ًا ‪:‬‬\n      ‫تعزيــره لقــاء حيازتــه العــرق املســكر بقصــد التعاطــي وذلــك بســجنه‬\n      ‫ملــدة ســنة واحــدة تبــدأ اعتبــار ًا مــن تاريــخ إيقافــه رابع ـ ًا ‪ :‬يؤخــذ التعهــد‬\n      ‫الشــديد علــى املدعــى عليــه بعــدم العــودة ملثــل مــا بــدر منــه هــذا مــا ظهــر‬\n      ‫لــي وبــه حكمــت وبعــرض احلكــم علــى املدعــى عليــه لــم يقنــع بــه وطلــب‬\n      ‫رفــع احلكــم حملكمــة االســتئناف فأجبتــه لطلبــه وأفهمتــه باســتالم‬\n      ‫نســخة احلكــم بعــد عشــرة أيــام وتقــدمي الئحــة اعتراضيــة خــال ثالثــن‬\n      ‫يومـ ًا مــن تاريــخ اســتالمه نســخة احلكــم كمــا قــرر املدعــي العــام عــدم‬\n      ‫االعتــراض علــى احلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n      ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/11/27‬ه ـ الســاعة ‪12:30‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثالثــة‬\n      ‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بنجــران برقــم‬\n      ‫‪ 332100533‬وتاريــخ ‪1434/1/17‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n      ‫فضيل ــة القاضــي باحملكمــة الشــيخ ‪..... /‬برقــم ‪ 33468786‬وتاريــخ‬\n      ‫‪1433/11/29‬ه ـ اخلــاص بدعــوى املدعــي العــام ضـ ــد ‪..... /‬يف قضيــة (‬\n      ‫شــرب مــادة العــرق املســكر وحيازتــه ) علــى الصفــة املوضحــة يف القــرار‬\n\n\n‫‪155‬‬\n\f‫املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار‬\n‫وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم واهلل‬\n             ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                 ‫‪156‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":151,"source_page_end":156,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3e922d169903901de362cfb6d623c74e37205000d00958f9c7b83db9248d272b","normalized_text_hash":"749fad15ca1107df6b03caed3cf9aeb08b0af301ca24b69cc44bd01fc96c080a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p151-33468786"},{"id":"e515ce02-7758-5227-a1c0-a34c020c0e6c","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -تعاطي املسكر وحيازته -عدم حضور املدعى عليه -إيقاف النظر حلن إحضار املدعى عليه -سند إجرائي .","document_number":"34211904","case_number":"33708187","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بصبياء","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/13","year":"1434","subject":"مسكر -تعاطي املسكر وحيازته -عدم حضور املدعى عليه -إيقاف النظر حلن إحضار املدعى عليه -سند إجرائي .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 34211904 :‬تاريخه‪1434/5/13:‬هـ‬\n                          ‫رقم الدعوى‪33708187:‬‬\n                   ‫رقم قرار التصديق من محكمة‬\n      ‫االستئناف‪ 34259848:‬تاريخه‪1434/07/04 :‬هـ‬\n\n\n      ‫مســكر ‪ -‬تعاطــي املســكر وحيازتــه ‪ -‬عــدم حضــور املدعــى عليــه ‪ -‬إيقــاف‬\n                           ‫النظــر حلــن إحضــار املدعــى عليــه ‪ -‬ســند إجرائــي ‪.‬‬\n\n\n\n\n        ‫‪-1‬املادة احلادية واألربعون بعد املائة من نظام اإلجراءات اجلزائية ‪.‬‬\n                   ‫‪ -2‬املادة الثالثة والثمانني من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وحيازتــه‬\n      ‫‪،‬وطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بحــد املســكر وتعزيــره‬\n      ‫لقــاء احليــازة ‪،‬حيــث قبــض علــى املدعــى عليــه مــن قبــل الشــرطة وكان‬\n      ‫يف ســيارته إثــر االشــتباه بــه وكان حــن القبــض عليــه يف حالــة غيــر‬\n      ‫طبيعية‪،‬وباستشــمامه اتضــح انبعــاث رائحــة املســكر مــن فمــه ‪،‬حيــث‬\n      ‫إنــه لــم يحضــر رغــم تبلغــه عــن طريــق الشــرطة‪،‬فرفعت اجللســة للكتابــة‬\n      ‫بخطــاب تعقيبــي للشــرطة إلحضــار املدعــى عليــه ‪،‬إال أنــه لــم يتــم‬\n      ‫إحضــاره ‪،‬وألنــه يتعــذر احلكــم يف الدعــوى بــدون حضــور املدعــى عليــه‬\n      ‫بنــاء علــى املــادة‪ 141‬مــن نظــام اإلجــراءات اجلزائيــة ‪،‬وألن بقــاء املعاملــة‬\n      ‫دون احلكــم فيهــا إضاعــة للوقــت وإهــدار للجلســات ‪،‬فقــد مت احلكــم‬\n      ‫بإيقــاف الدعــوى حلــن إحضــار املدعــى عليــه وذلــك بنــاء علــى املــادة ‪83‬‬\n\n‫‪157‬‬\n\f‫مــن نظــام املرافعــات الشــرعية ‪،‬واعتــرض املدعــي العــام بــدون الئحــة‬\n                            ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬‫ُ‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة العامــة‬\n‫بصبيــاء وبنــاء علــى املعاملــة الــواردة لنــا مــن هيئــة التحقيــق واالدعــاء‬\n‫العــام مبحافظــة صبيــا برقــم ه ـ ج‪ 224/2/2‬وتاريــخ ‪1433/01/26‬ه ـ‬\n‫احملدثــة إحالتهــا برقــم ‪ 33078187‬وتاريــخ ‪ 1434/2/2‬ه ـ احملــدث‬\n‫قيدهــا رقــم ‪ 332257876‬ففــي يــوم الســبت املوافــق‪1434/02/02‬‬\n‫ه ـ افتتحــت اجللســة الســاعة ‪ 11 : 00‬وفيهــا قــدم املدعــي العــام بصبيــا‬\n‫‪.....‬دعــواه ضــد ‪ .....‬الغائــب عــن مجلــس احلكــم قائــا يف دعــواه انــه‬\n‫بتاريــخ ‪1432/12/29‬ه ـ مت القبــض علــى املدعــى عليــه مــن قبــل أفــراد‬\n‫البحــث والتحريــات بشــرطة صبيــا وهــو كان يف ســيارته يف محطــة‬\n‫‪.....‬أثنــاء االشــتباه فيــه وكان حــن القبــض يف حالــة غيــر طبيعيــة‬\n‫متعاطيــا ملــادة املســكر ‪ .‬وباستشــمامه اتضــح أن رائحــة املســكر تفــوح‬\n‫مــن فمــه ومت ضبــط قــارورة مــاء صحــة صغيــرة بهــا مــادة أثبــت التقريــر‬\n‫الفنــي إيجابيــة تلــك املــادة للكحــول األثيلــي املســكر بنســبة ‪%31‬‬\n‫وباســتجوابه أقــر أنــه مت القبــض عليــه عندمــا كان نائمــا يف ســيارته‬\n‫يف محطــة ‪.....‬وكان متعاطيــا ملــادة املســكر وأمــا مــادة املســكر‬\n‫التــي عثــرت بحوزتــه وهــي قــارورة مــاء صحــة صغيــر حصــل عليهــا مــن‬\n‫شــخص باكســتاني ال يعرفــه وقــد أســفر التحقيــق عــن توجيــه االتهــام‬\n‫لــه بتعاطيــه ملــادة املســكر وحيازتــه لــه وذلــك إلقــراره املــدون ص (‪)4‬‬\n‫بدفتــر التحقيــق املرفــق ومحضــر القبــض املرفــق لفــة رقــم (‪ )2‬ومحضــر‬\n\n                                                                                     ‫‪158‬‬\n\f      ‫اإلستشــمام املــدون ص (‪ )1‬بدفتــر التحقيــق املرفــق ‪ .‬والتقريــر الفنــي‬\n      ‫املرفــق رقــم (‪ )11‬وبالبحــث عــن ســوابقه لــم يعثــر لــه ســابقه مســجله‬\n      ‫وحيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرعا‬\n      ‫لــذا أطلــب إثبــات مــا نســب إليــه احلكــم عليــه بحــد املســكر ‪ ،‬وتعزيــره‬\n      ‫شــرعا لقــاء حيازتــه قــارورة مــاء صغيــر بهــا مســكر هكــذا ادعــى هــذا‬\n      ‫كمــا ســبق أن مت تبليــغ املدعــى عليــه للحضــور للمحكمــة مبوجــب‬\n      ‫خطــاب شــرطة صبيــا رقــم ‪.....‬يف ‪ 1433/02/22‬ه ـ وخطابهــم رقــم ‪.....‬‬\n      ‫يف ‪1433/08/06‬ه ـ ونظــر ًا ألن املدعــى عليــه لــم يحضــر رغــم تبلغــه‬\n      ‫وبنــاء علــى املــادة احلاديــة واألربعــن بعــد املائــة فقــد جــرت الكتابــة إلــى‬\n      ‫شــرطة صبيــا إليقافــه وإحضــاره للمحكمــة ولــم يتــم إحضــاره هــذا‬\n      ‫اليــوم وعليــه فقــد قــررت كتابــة خطــاب تعقيبــي وحتديــد موعــد آخــر‬\n      ‫ويف جلســة أخــرى حضــر املدعــي العــام ولــم يحضــر املدعــى عليــه وقــد‬\n      ‫ســبق كتابــة خطــاب إحلاقــي باألمــر بإيقــاف املدعــى عليــه وإحضــاره‬\n      ‫للمحكمــة يف هــذا اليــوم إال أنــه لــم يتــم إنفــاذ ذلــك وعليــه ونظــرا ألنــه‬\n      ‫يتعــذر احلكــم يف الدعــوى بــدون حضــور املدعــى عليــه بنــاء علــى املــادة‬\n      ‫احلاديــة واألربعــن بعــد املائــة مــن نظــام اإلجــراءات اجلزائيــة كمــا أنــه‬\n      ‫مت األمــر بإيقافــه مرتــن ولــم يتــم إنفــاذ األمــر وألن يف بقــاء املعاملــة‬\n      ‫لــدى احملكمــة دون أن ميكــن احلكــم فيهــا إضاعــة للوقــت وإهــدارا‬\n      ‫للجلســات دون طائــل لــذا فقــد قــررت إيقــاف النظــر يف هــذه الدعــوى‬\n      ‫حلــن إحضــار املدعــى عليــه بنــاء علــى املــادة الثالثــة والثمانــن مــن نظــام‬\n      ‫املرافعــات الشــرعية وبعرضــه علــى املدعــي العــام قــرر عــدم قناعتــه‬\n      ‫طالبــا رفــع املعاملــة حملكمــة االســتئناف دون الئحــة اعتراضيــة لكونــه‬\n      ‫يرغــب أن يتــم بعــث املعاملــة إلــى الشــرطة إلحضــار املدعــى عليــه بالقــوة‬\n\n\n‫‪159‬‬\n\f‫اجلبريــة وعليــه فقــد أجبتــه لطلبــه وأمــرت برفــع املعاملــة إلــى محكمــة‬\n‫االســتئناف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                               ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/05/11‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بصبيــا برقــم ‪332257876‬‬\n‫وتاريــخ ‪1434/5/25‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيل ــة القاضي‬\n‫باحملكمــة الشــيخ ‪..... /‬برقــم ‪ 34211904‬وتاريــخ ‪1434/5/13‬ه ـ‬\n‫اخلــاص بدعــوى املدعــي العــام ضــد ‪..... /‬يف قضيــة (مســكر) علــى‬\n‫الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة تقــررت‬\n‫املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                               ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪160‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":157,"source_page_end":160,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"78bfec5fed7d2365aa4467d5a4168bb05240207d08f8e1d052cd883389768c06","normalized_text_hash":"e9bb3d0cc5efe21a0eae8a9ae836053aceefe022fdd5c6d0f888a0858b141a3b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p157-34211904"},{"id":"45640cd6-c31a-563e-b339-f488177daf78","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -حيازة احلبوب املمنوعة بغرض االستعمال -تخفيف العقوبة لقلة الكمية -تدرأ احلدود بالشبهات -التعزير باجللد والسجن واملنع من السفر .","document_number":"3458980","case_number":"34107889","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعرعر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/9","year":"1434","subject":"مسكر -شرب املسكر -حيازة احلبوب املمنوعة بغرض االستعمال -تخفيف العقوبة لقلة الكمية -تدرأ احلدود بالشبهات -التعزير باجللد والسجن واملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"          ‫رقم الصك‪ 3458980:‬تاريخه‪1434/3/9:‬هـ‬\n                         ‫رقم الدعوى‪34107889:‬‬\n                   ‫رقم قرار التصديق من محكمة‬\n      ‫االستئناف‪ 34188286:‬تاريخه‪1434/04/15:‬هـ‬\n\n\n      ‫مســكر ‪ -‬شــرب املســكر ‪ -‬حيــازة احلبــوب املمنوعــة بغــرض االســتعمال‬\n      ‫‪ -‬تخفيــف العقوبــة لقلــة الكميــة ‪ -‬تــدرأ احلــدود بالشــبهات ‪ -‬التعزيــر‬\n                                         ‫باجللــد والســجن واملنــع مــن الســفر ‪.‬‬\n\n\n\n\n                  ‫‪ -1‬قوله صلى اهلل عليه وسلم ( ادرؤوا احلدود بالشبهات ) ‪.‬‬\n                  ‫‪ -2‬املادة ‪ 41‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n                  ‫‪ -3‬املادة ‪ 60‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n                  ‫‪ -4‬املادة ‪ 56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وحيــازة حبــة‬\n      ‫واحــدة مــن حبــوب االمفيتامــن وطلــب إثبــات مــا أســند إليــه واحلكــم‬\n      ‫عليه بحد املســكر وســجنه ومنعه من الســفر والتشــديد عليه للســوابق‬\n      ‫‪،‬حيــث مت االشــتباه باملدعــى عليــه مــن قبــل فرقــة مكافحــة املخــدرات‬\n      ‫وكان متوقــف أمــام منزلــه وعنــد توجــه الدوريــة لــه قــام بالتوجــه إلــى‬\n      ‫بــاب منزلــه ورمــي شــيء مــن جيبــه ومتــت الســيطرة عليــه قبــل دخولــه‬\n      ‫املنــزل وبتفتيشــه لــم يتــم العثــور علــى شــيء معه ومبشــاهدة ما قــام برميه‬\n      ‫عثــر علــى حبــة يشــتبه أن تكــون مــن احلبــوب احملظــورة وباستشــمامه‬\n\n‫‪161‬‬\n\f‫اتضــح انبعــاث رائحــة املســكر مــن أنفاســه وأثبــت التقريــر الكيميائــي‬\n‫الشــرعي إيجابيــة العينــة املضبوطــة ملــادة االمفيتامــن ‪،‬صــادق املدعــى‬\n‫عليــه علــى احليــازة وأنكــر شــرب املســكر ‪،‬وبنــاء علــى مــا تقــدم‬\n‫حكمــت احملكمــة بالســجن أربعــة أشــهر وجلــده تســع ًا وســبعني‬\n‫جلــدة تعزيــرا علــى دفعتــن األولــى قدرهــا ‪ 39‬جلــده والثانيــة قدرهــا‬\n‫‪ 40‬جلــده لقــاء توجــه التهمــة لشــرب املســكر ومنعــه مــن الســفر مــدة‬\n‫ســنتني وصــرف النظــر عــن طلــب املدعــي العــام بإقامــة حــد املســكر‬\n‫وقنــع املدعــى عليــه واعتــرض املدعــي العــام مكتفيــا بالئحــة الدعــوى‬\n                            ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬   ‫ُ‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة العامــة‬\n‫بعرعــر وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بعرعــر برقــم ‪ 34107889‬وتاريــخ ‪ 1434/03/04‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 34565415‬وتاريــخ ‪ 1434/03/04‬ه ـ ففــي يــوم‬\n‫االثنــن املوافــق‪ 1434/03/09‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 45‬‬\n‫وفيهــا حضــر املدعــي العــام ‪.....‬وادعــى قائال بصفتي مدعيـ ًا عام ًا بدائرة‬\n‫االدعــاء العــام لفــرع الهيئــة مبنطقــة احلــدود الشــمالية أدعــي ‪.....‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬فأنــه بتاريــخ ‪1434/2/19‬ه ـ‬\n‫وأثنــاء قيــام فرقــة مكافحــة املخــدرات بعملهــا املعتــاد وذلــك مبســح‬\n‫االماكــن املشــبوهة مــن مروجــي ومســتخدمي املخــدرات وأثنــاء املســح‬\n‫حلــي ‪.....‬بإســكان ‪ ..........‬مت االشــتباه يف شــخص كان متوقــف أمــام‬\n‫منزلــه وعنــد توجيــه الدوريــة الرســمية إليــه قــام بالتوجــه إلــى بــاب منزلــه‬\n\n                                                                                        ‫‪162‬‬\n\f      ‫وأخــرج شــيء مــن جيبــه األميــن وقــام برميــه ومتــت الســيطرة عليــه قبــل‬\n      ‫دخولــه املنــزل وبتفتيشــه شــخصي ًا لــم يعثــر علــى أي شــيء مــن املمنوعــات‬\n      ‫ومبشــاهدة مــا قــام برميــه عثــر علــى حبــة بنية اللون يشــتبه أن تكون من‬\n      ‫احلبــوب احملظــورة كانــت علــى األرض أمــام بــاب املنــزل‪ ،‬وباستشــمامه‬\n      ‫اتضــح انبعــاث رائحــة مــن أنفاســه تشــبه رائحــة املســكر ‪ ،‬فتــم ضبطــه‬\n      ‫‪ .‬وباســتجوابه‪ /‬أقــر بشــرب املســكر وحيــازة حبــة واحــدة مــن حبــوب‬\n      ‫االمفيتامــن احملظــورة بقصــد التعاطــي ‪ ،‬واســتعماله لنوعهــا يف‬\n      ‫الســابق ‪ .‬وقــد أثبــت التقريــر الكيميائــي الشــرعي الصــادر مــن مركــز‬\n      ‫الســموم بتبــوك رقــم (‪ ).....‬لعــام ‪1434‬ه ـ إيجابيــة العينــة املرســلة للمــادة‬\n      ‫االمفيتامــن املنبــه للجهــاز العصبــي وهــو مــن املؤثــرات العقليــة اخلاضعــة‬\n      ‫للرقابــة واملنــوه عنــه باجلــدول الثانــي فئــة (ب) يف تعميــم صاحــب الســمو‬\n      ‫امللكــي وزيــر الداخليــة رقــم (‪ )89400/19‬وتاريخ‪1426/10/25‬هــ‪.‬‬\n      ‫وقــد انتهــى التحقيــق إلــى اتهــام‪ ،...../‬بشــرب املســكر وحيــازة حبــة‬\n      ‫واحــدة مــن احلبــوب احملتويــة علــى مــادة االمفيتامــن املنبهــة للجهــاز‬\n      ‫العصبــي بقصــد االســتعمال‪ ،‬واســتعماله لنوعهــا يف الســابق ‪ ،‬املجــرم‬\n      ‫نظامــا بنــص املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة ‪ ،‬الصــادر باملرســوم امللكي رقــم (م‪ )39/‬وتاريخ ‪1426/7/8‬هـ‬\n      ‫‪.‬وذلــك لألدلــة والقرائــن التاليــة‪ -1 :‬مــا جــاء بأقوالــه املدونــة علــى‬\n      ‫محضــر االســتجواب املرفــق لفــة رقــم (‪ -2.)6-7‬مــا جــاء مبحضــر‬\n      ‫القبــض املرفــق املــدون علــى الصفحــة رقــم (‪ )12‬لفــة رقــم (‪ -3.)1‬مــا‬\n      ‫جــاء مبحضــر االستشــمام املرفــق املــدون علــى الصفحــة رقــم (‪ )13‬لفــة‬\n      ‫رقــم (‪ -4.)1‬مــا جــاء بالتقريــر الكيميائــي الشــرعي املرفــق لفــة رقــم‬\n      ‫(‪ . )23‬وحيــث أن مــا أقــدم عليــه املتهــم وهــو بكامــل أهليتــه املعتبــرة‬\n\n\n‫‪163‬‬\n\f‫شــرعا فعــل محــرم ومعاقــب عليــه شــرعا ومجــرم نظامــا بنــص املــادة‬\n‫الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪ ،‬الصــادر‬\n‫باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ لــذا أطلــب إثبــات‬\n‫إدانتــه مبــا أســند إليــه واحلكــم عليــه مبــا يلــي‪ -1 :‬عقوبــة حــد املســكر‪.‬‬\n‫‪ -2‬عقوبــة الســجن وفقــا للفقــرة األولــى مــن املــادة (‪ )41‬مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬وإعمــال الفقــرة األولــى مــن‬\n                                              ‫املــادة (‪ )62‬مــن النظــام نفســه‪.‬‬\n‫‪ -3‬عقوبــة املنــع مــن الســفر خــارج اململكــة وفقــا للفقــرة األولــى مــن‬\n‫املــادة (‪ )56‬مــن النظــام نفســه ‪ ،‬والتشــديد عليــه نظــر ًا لســوابقه‬\n‫وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه احلاضــر أجــاب قائــا ‪:‬‬\n‫مــا ذكــره املدعــي العــام مــن حيازتــي للحبــة بقصــد االســتعمال صحيــح‬\n‫ومــا ذكــره مــن شــربي للمســكر فغيــر صحيــح مطلقــا وبســؤال املدعــي‬\n‫العــام البينــة علــى شــرب املدعــى عليــه للمســكر أجــاب قائــا بينتــي مــا‬\n‫جــاء يف إقــرار لــدى املدعــى عليــه لــدى احملقــق واملرفــق لكــم بطيــات‬\n‫املعاملــة وكذلــك مــا جــاء مبحضر االستشــمام املرفــق لكم ‪ ،‬هذا وقد‬\n‫جــرى منــا االطــاع علــى محاضــر التحقيــق املرفقــة علــى لفــة رقــم (‪)7،6‬‬\n‫مــن طيــات املعاملــة ووجــدت فيهــا اقــرار املدعــى عليــه بشــرب املســكر‬\n‫وانــه كان بحالــة غيــر طبيعيــة أثنــاء القبــض عليــه وبعــرض ذلــك علــى‬\n‫املدعــى عليــه أجــاب قائــا ‪ :‬أننــي لــم أقــر بذلــك ولــم أطلــع علــى مــا‬\n‫كتــب يف التحقيــق ولــم أقــرأ ذلــك كلــه وإمنــا بصمــت مباشــرة ‪.‬هكــذا‬\n‫أجــاب كمــا جــرى منــا االطــاع علــى محضــر االستشــمام املــدون علــى‬\n‫صحيفــة رقــم (‪ )13‬مــن ملــف ضبــط إجــراءات االســتدالل يف قضايــا‬\n‫املخــدرات لفــه رقــم (‪ )1‬مــن طيــات املعاملــة ونــص احلاجــة منــه ‪ (( :‬كان‬\n\n\n                                                                                      ‫‪164‬‬\n\f      ‫تطلــع مــن فــاه رائحــة تشــبه رائحــة العــرق املســكر ‪...‬ومت التأكــد بأنهــا‬\n      ‫تشــبه رائحــة العــرق املســكر ‪ ))...‬أ‪.‬ه ـ وبعــرض ذلــك علــى املدعــى عليــه‬\n      ‫أنكــر ذلــك مطلقـ ًا ‪ ،‬وبســؤال املدعــي العــام هــل لديــه مزيــد بينــة أجــاب‬\n      ‫قائــا ‪ :‬ليــس لــدي ســوا مــا قدمتــه وبســؤال املدعــى عليــه عــن الســوابق‬\n      ‫املدونــة بســجله وعددهــا خمــس ســوابق منهــا قضيــة ترويــج للمخــدرات‬\n      ‫صــادق عليهــا جميع ـ ًا فبنــاء علــى مــا تقــدم مــن الدعــوى ومصادقــة‬\n      ‫املدعــى عليــه علــى دعــوى احليــازة وإنــكاره لدعــوى الشــرب وعــدم قيــام‬\n      ‫البينــة املوصلــة متامــا علــى ذلــك وملــا ورد عنــه صلــى اهلل عليــه وســلم مــن‬\n      ‫قولــه «ادرؤوا احلــدود بالشــبهات « ‪ .‬لــذا كلــه فقــد ثبــت لــدي إدانــة‬\n      ‫املدعــى عليــه ‪.....‬بحيــازة حبــة واحــدة مــن حبــوب االمفيتامــن بقصــد‬\n      ‫االســتعمال واســتعماله لنوعهــا مــن الســابق ورددت طلــب املدعــي العــام‬\n      ‫اثبــات ادانتــه بشــرب املســكر وحكمــت بعــدم ادانتــه بشــرب املســكر‬\n      ‫ونظــرا لتعــدد ســوابقه وكــون إحداهــا مــن جنــس هــذه الدعــوى وذلــك‬\n      ‫موجــب للتشــديد ولكــون الكميــة املضبوطــة قليلــة جــد ًا وذلــك موجــب‬\n      ‫للتخفيــف فقــد حكمــت عليــه لقــاء احليــازة ولقــاء توجــه التهمــة بحقــه‬\n      ‫بشــرب املســكر بنــاء علــى اإلقــرار املــدون لــدى هيئــة التحقيــق واالدعــاء‬\n            ‫العــام وبنــاء علــى محضــر االستشــمام املشــار إليــه بعاليــه مبــا يلــي‪:‬‬\n      ‫أوال‪ :‬ســجنه ملــدة اربعــة اشــهر تبــدأ مــن تاريــخ ايقافــه املوافــق‬\n      ‫‪1434/2/19‬ه ـ وذلــك بنــاء علــى املــادة (‪)41‬مــن نظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة وإعمــاال للمــادة (‪ )60‬مــن ذات النظــام‪.‬‬\n      ‫ثانيــا‪ :‬جلــده تســعة وســبعني ســوط ًا تعزيــرا علــى دفعتــن األولــى تســعة‬\n      ‫وثالثــن ســوطا والثانيــة أربعــن ســوطا بينهمــا مــاال يقــل عــن عشــرة أيــام‬\n                                 ‫وذلــك لقــاء توجــه التهمــة عليــه بشــرب املســكر‬\n\n\n‫‪165‬‬\n\f‫ثالثــا ‪ :‬منعــه مــن الســفر خــارج اململكــة بعــد انتهــاء محكوميتــه وملــدة‬\n‫ســنتني بنــاء علــى املــادة (‪ )56‬مــن النظــام املشــار إليــه رابعــا‪ :‬صرفــت‬\n‫النظــر عــن طلــب املدعــي العــام إقامــة حــد املســكر عليــه بنــاء علــى مــا‬\n‫ذكــر بعاليــه ‪ .‬وبعــرض احلكــم علــى املدعــى عليــه قــرر قناعتــه به كما‬\n‫قــرر املدعــي العــام االعتــراض علــى احلكــم واكتفــى بالئحــة الدعــوى‬\n‫كالئحــة اعتراضيــة‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                      ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/03/09‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة األولــى‬\n‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة اجلــوف علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بعرعــر برقــم‬\n‫‪ 34565415‬وتاريــخ ‪1434/3/18‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ‪ ..... /‬املســجل برقــم ‪3458980‬‬\n‫وتاريــخ ‪1434/3/9‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد‪..... /‬يف‬\n‫قضيــة مســكر ومخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو‬\n‫مــدون ومفصــل بــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n‫فقــد قررنــا املصادقــة علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                          ‫محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                     ‫‪166‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":161,"source_page_end":166,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"190a3344d24c09487f50f5658d3edd661ff042c5a6eb1b9bffd878e67e89590f","normalized_text_hash":"703c5dd46d5c84154decb446df4390a3141530c9ed68502b57398ae81c666b06","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p161-3458980"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
